def fib_sum(n: int) -> int:
    """Compute the sum of the first n Fibonacci numbers."""
    if n <= 0:
        return 0

    fib_values = []
    a, b = 1, 1

    for _ in range(n):
        fib_values.append(a)
        a, b = b, a + b

    return sum(fib_values)


def main() -> None:
    result = fib_sum(20)
    print(result)
    print(result)


if __name__ == "__main__":
    main()

