module benchmark/solution

import std/io (println)

type Mat = {m00: int, m01: int, m02: int, m10: int, m11: int, m12: int, m20: int, m21: int, m22: int}

pure func identity() -> Mat = {m00: 1, m01: 0, m02: 0, m10: 0, m11: 1, m12: 0, m20: 0, m21: 0, m22: 1}

pure func transition() -> Mat = {m00: 1, m01: 1, m02: 0, m10: 0, m11: 1, m12: 1, m20: 1, m21: 0, m22: 0}

pure func matMul(a: Mat, b: Mat) -> Mat =
  {m00: (a.m00 * b.m00 + a.m01 * b.m10 + a.m02 * b.m20) % 1000000007,
   m01: (a.m00 * b.m01 + a.m01 * b.m11 + a.m02 * b.m21) % 1000000007,
   m02: (a.m00 * b.m02 + a.m01 * b.m12 + a.m02 * b.m22) % 1000000007,
   m10: (a.m10 * b.m00 + a.m11 * b.m10 + a.m12 * b.m20) % 1000000007,
   m11: (a.m10 * b.m01 + a.m11 * b.m11 + a.m12 * b.m21) % 1000000007,
   m12: (a.m10 * b.m02 + a.m11 * b.m12 + a.m12 * b.m22) % 1000000007,
   m20: (a.m20 * b.m00 + a.m21 * b.m10 + a.m22 * b.m20) % 1000000007,
   m21: (a.m20 * b.m01 + a.m21 * b.m11 + a.m22 * b.m21) % 1000000007,
   m22: (a.m20 * b.m02 + a.m21 * b.m12 + a.m22 * b.m22) % 1000000007}

pure func matPow(m: Mat, e: int) -> Mat =
  if e == 0 then identity()
  else if e % 2 == 0 then let half = matPow(m, e / 2) in matMul(half, half)
  else matMul(m, matPow(m, e - 1))

pure func countNo101(n: int) -> int =
  let p = matPow(transition(), n) in
  (p.m00 + p.m01 + p.m02) % 1000000007

export func main() -> () ! {IO} {
  println(show(countNo101(1000000000000000000)));
  println(show(countNo101(987654321987654321)))
}

module benchmark/solution

type Instr = PUSH(int) | ADD | SUB | MUL | DUP | OVER | SWAP | POP | JMP(int) | JMPZ(int) | JMPGT(int) | HALT

pure func getInstr(prog: [Instr], idx: int) -> Instr =
  match prog {
    [] => HALT,
    x :: rest => if idx == 0 then x else getInstr(rest, idx - 1)
  }

func printStack(stack: [int]) -> () ! {IO} =
  match stack {
    [] => (),
    x :: rest => {
      printStack(rest);
      println(show(x))
    }
  }

func run(prog: [Instr], stack: [int], pc: int, steps: int) -> (int, [int]) ! {IO} {
  let instr = getInstr(prog, pc);
  let newSteps = steps + 1;
  match instr {
    HALT => (newSteps, stack),
    PUSH(k) => run(prog, k :: stack, pc + 1, newSteps),
    ADD => match stack {
      b :: a :: rest => run(prog, (a + b) :: rest, pc + 1, newSteps),
      _ => (newSteps, stack)
    },
    SUB => match stack {
      b :: a :: rest => run(prog, (a - b) :: rest, pc + 1, newSteps),
      _ => (newSteps, stack)
    },
    MUL => match stack {
      b :: a :: rest => run(prog, (a * b) :: rest, pc + 1, newSteps),
      _ => (newSteps, stack)
    },
    DUP => match stack {
      a :: rest => run(prog, a :: a :: rest, pc + 1, newSteps),
      _ => (newSteps, stack)
    },
    OVER => match stack {
      b :: a :: rest => run(prog, a :: b :: a :: rest, pc + 1, newSteps),
      _ => (newSteps, stack)
    },
    SWAP => match stack {
      b :: a :: rest => run(prog, a :: b :: rest, pc + 1, newSteps),
      _ => (newSteps, stack)
    },
    POP => match stack {
      _ :: rest => run(prog, rest, pc + 1, newSteps),
      _ => (newSteps, stack)
    },
    JMP(d) => run(prog, stack, pc + d, newSteps),
    JMPZ(d) => match stack {
      v :: rest => if v == 0 then run(prog, rest, pc + d, newSteps) else run(prog, rest, pc + 1, newSteps),
      _ => (newSteps, stack)
    },
    JMPGT(d) => match stack {
      b :: a :: rest => if a > b then run(prog, rest, pc + d, newSteps) else run(prog, rest, pc + 1, newSteps),
      _ => (newSteps, stack)
    }
  }
}

export func main() -> () ! {IO} {
  let prog = [
    PUSH(252),
    PUSH(105),
    OVER,
    OVER,
    SUB,
    JMPZ(12),
    OVER,
    OVER,
    JMPGT(4),
    OVER,
    SUB,
    JMP(-9),
    SWAP,
    OVER,
    SUB,
    SWAP,
    JMP(-14),
    POP,
    HALT
  ];
  match run(prog, [], 0, 0) {
    (steps, stack) => {
      printStack(stack);
      println("steps: ${show(steps)}")
    }
  }
}

