module benchmark/solution
import std/io (println)
import std/fs (readFile, writeFile)
import std/json (decode, get, asString, asNumber, asArray)
import std/string (foldChars)
import std/math (floatToInt)
import std/option (Some, None, Option)
import std/list as L

-- Count dots in a string for version validation
pure func countDots(s: string) -> int =
  foldChars(\acc c. if c == "." then acc + 1 else acc, 0, s)

-- Helper: extract string from Json or return default
pure func getStringField(obj: Json, key: string, def: string) -> string =
  match get(obj, key) {
    Some(j) => match asString(j) { Some(s) => s, None => def },
    None => def
    }

-- Helper: extract int from Json or return default
pure func getIntField(obj: Json, key: string, def: int) -> int =
  match get(obj, key) {
    Some(j) => match asNumber(j) { Some(nf) => floatToInt(nf), None => def },
    None => def
    }

-- Helper: extract array field, return list or empty
pure func getArrayField(obj: Json, key: string) -> [Json] =
  match get(obj, key) {
    Some(j) => match asArray(j) { Some(a) => a, None => [] },
    None => []
    }

export func main() -> () ! {IO, FS} {
  let jsonContent = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  writeFile("app_config.json", jsonContent);

  match decode(readFile("app_config.json")) {
    Err(msg) => println("Parse error: ${msg}"),
    Ok(json) => {
      let appName = getStringField(json, "app_name", "unknown");
      let version = getStringField(json, "version", "0.0.0");
      let port = getIntField(json, "port", 80);

      let portOk = port >= 1024 && port <= 65535;
      let versionOk = countDots(version) == 2;

      let features = getArrayField(json, "features");
      let featCount = L.length(features);
      let featuresOk = featCount > 0;

      if portOk && versionOk && featuresOk then {
        println("Loaded ${appName} v${version} on port ${show(port)} with ${show(featCount)} features")
        } else {
        println("Validation failed")
        }
      }
    }
}

