package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

type Config struct {
	AppName  string   `json:"app_name"`
	Version  string   `json:"version"`
	Port     int      `json:"port"`
	Features []string `json:"features"`
}

func validateConfig(cfg *Config) error {
	if cfg.Port < 1024 || cfg.Port > 65535 {
		return fmt.Errorf("port %d is not between 1024 and 65535", cfg.Port)
	}

	dots := strings.Count(cfg.Version, ".")
	if dots != 2 {
		return fmt.Errorf("version %s does not contain exactly two dots", cfg.Version)
	}

	if len(cfg.Features) == 0 {
		return fmt.Errorf("features list must not be empty")
	}

	return nil
}

func main() {
	data, err := os.ReadFile("app_config.json")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading config file: %v\n", err)
		os.Exit(1)
	}

	var cfg Config
	err = json.Unmarshal(data, &cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error parsing JSON: %v\n", err)
		os.Exit(1)
	}

	err = validateConfig(&cfg)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Validation error: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Loaded %s v%s on port %d with %d features\n", cfg.AppName, cfg.Version, cfg.Port, len(cfg.Features))
}

