const fs = require("fs");
const path = require("path");

function loadAndValidateConfig(configPath) {
  const content = fs.readFileSync(configPath, "utf-8");
  const config = JSON.parse(content);

  // Validate port is between 1024 and 65535
  if (config.port < 1024 || config.port > 65535) {
    throw new Error(`Port must be between 1024 and 65535, got ${config.port}`);
  }

  // Validate version contains exactly two dots (X.X.X format)
  if (!/^\d+\.\d+\.\d+$/.test(config.version)) {
    throw new Error(`Version must contain exactly two dots (X.Y.Z format), got ${config.version}`);
  }

  // Validate features list is not empty
  if (!Array.isArray(config.features) || config.features.length === 0) {
    throw new Error("Features list must not be empty");
  }

  return config;
}

function main() {
  const configPath = path.join(__dirname, "app_config.json");

  // Create the config file if it doesn't exist
  if (!fs.existsSync(configPath)) {
    const config = {
      app_name: "MyApp",
      version: "1.0.0",
      port: 8080,
      features: ["logging", "auth", "api"],
    };
    fs.writeFileSync(configPath, JSON.stringify(config, null, 2), "utf-8");
  }

  const config = loadAndValidateConfig(configPath);

  console.log(
    `Loaded ${config.app_name} v${config.version} on port ${config.port} with ${config.features.length} features`
  );
}

main();

