module benchmark/solution

type Tree = Leaf | Node(Tree, int, Tree)

func insert(tree: Tree, value: int) -> Tree =
  match tree {
    Leaf => Node(Leaf, value, Leaf),
    Node(left, current, right) =>
      if value < current then Node(insert(left, value), current, right)
      else if value > current then Node(left, current, insert(right, value))
      else tree
  }

func contains(tree: Tree, value: int) -> bool =
  match tree {
    Leaf => false,
    Node(left, current, right) =>
      if value == current then true
      else if value < current then contains(left, value)
      else contains(right, value)
  }

func size(tree: Tree) -> int =
  match tree {
    Leaf => 0,
    Node(left, _, right) => 1 + size(left) + size(right)
  }

func isBST(tree: Tree, lower: int, upper: int) -> bool =
  match tree {
    Leaf => true,
    Node(left, value, right) =>
      value > lower && value < upper &&
      isBST(left, lower, value) &&
      isBST(right, value, upper)
  }

func insertPreservesBST(value: int) -> bool =
  isBST(insert(Leaf, value), -999999, 999999)

func insertThenFind(value: int) -> bool =
  contains(insert(Leaf, value), value)

export func main() -> () ! {IO} {
  let tree = insert(insert(insert(Leaf, 5), 3), 7);
  println(show(size(tree)));
  println(show(contains(tree, 3)));
  println(show(contains(tree, 4)));
  println(show(isBST(tree, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}

