from dataclasses import dataclass
from typing import Generic, Optional, TypeVar

T = TypeVar('T')

@dataclass
class Node(Generic[T]):
    value: T
    left: 'Optional[Node[T]]'
    right: 'Optional[Node[T]]'

@dataclass
class Leaf(Generic[T]):
    pass

BST = Node | Leaf

def size(tree: BST) -> int:
    """Return the number of nodes in the tree."""
    match tree:
        case Leaf():
            return 0
        case Node(left=left, right=right):
            return 1 + size(left) + size(right)

def contains(tree: BST, value: int) -> bool:
    """Check if a value exists in the tree."""
    match tree:
        case Leaf():
            return False
        case Node(value=v, left=left, right=right):
            if value == v:
                return True
            elif value < v:
                return contains(left, value)
            else:
                return contains(right, value)

def insert(tree: BST, value: int) -> BST:
    """Insert a value into the tree. Duplicates are not allowed."""
    match tree:
        case Leaf():
            return Node(value=value, left=Leaf(), right=Leaf())
        case Node(value=v, left=left, right=right):
            if value == v:
                return tree
            elif value < v:
                return Node(value=v, left=insert(left, value), right=right)
            else:
                return Node(value=v, left=left, right=insert(right, value))

def isBST(tree: BST, min_val: int, max_val: int) -> bool:
    """Validate that the tree is a proper BST within the given bounds."""
    match tree:
        case Leaf():
            return True
        case Node(value=v, left=left, right=right):
            if v <= min_val or v >= max_val:
                return False
            return isBST(left, min_val, v) and isBST(right, v, max_val)

def insertPreservesBST(value: int) -> bool:
    """Proof that inserting into a BST preserves the BST property."""
    tree = insert(insert(insert(Leaf(), 5), 3), 7)
    new_tree = insert(tree, value)
    return isBST(new_tree, -999999, 999999)

def insertThenFind(value: int) -> bool:
    """Proof that a value can be found after insertion."""
    tree = insert(insert(insert(Leaf(), 5), 3), 7)
    new_tree = insert(tree, value)
    return contains(new_tree, value)

def main() -> None:
    """Main function to demonstrate the BST operations."""
    tree = insert(insert(insert(Leaf(), 5), 3), 7)

    print(size(tree))
    print(contains(tree, 3))
    print(contains(tree, 4))
    print(isBST(tree, -999999, 999999))
    print(insertPreservesBST(42))
    print(insertThenFind(42))

if __name__ == "__main__":
    main()

