module benchmark/solution

pure func isLeapYear(year: int) -> bool =
  if year % 400 == 0 then true
  else if year % 100 == 0 then false
  else if year % 4 == 0 then true
  else false

pure func daysInMonth(month: int, year: int) -> int =
  if month == 2 && isLeapYear(year) then 29
  else if month == 2 then 28
  else if month == 4 || month == 6 || month == 9 || month == 11 then 30
  else 31

export func main() -> () ! {IO} {
  println(show(isLeapYear(1900)));
  println(show(isLeapYear(2000)));
  println(show(isLeapYear(2024)));
  println(show(isLeapYear(2023)));
  println(show(daysInMonth(2, 2000)));
  println(show(daysInMonth(2, 1900)));
  println(show(daysInMonth(4, 2023)))
}

module benchmark/solution

pure func det2(a: int, b: int, c: int, d: int) -> int =
  a * d - b * c

pure func det3(a: int, b: int, c: int, d: int, e: int, f: int, g: int, h: int, i: int) -> int =
  a * det2(e, f, h, i) - b * det2(d, f, g, i) + c * det2(d, e, g, h)

pure func identityDet() -> bool =
  det3(1, 0, 0, 0, 1, 0, 0, 0, 1) == 1

pure func zeroRowDet(a: int, b: int, c: int, d: int, e: int, f: int) -> bool =
  det3(a, b, c, 0, 0, 0, d, e, f) == 0

export func main() -> () ! {IO} {
  println(show(det2(3, 8, 4, 6)));
  println(show(det3(6, 1, 1, 4, -2, 5, 2, 8, 7)));
  println(show(det3(1, 0, 0, 0, 1, 0, 0, 0, 1)));
  println(show(identityDet()));
  println(show(zeroRowDet(3, 5, 7, 2, 4, 6)))
}

