def encode(s: str) -> str:
    if not s:
        return ""

    result = []
    i = 0
    while i < len(s):
        char = s[i]
        count = 1
        while i + count < len(s) and s[i + count] == char:
            count += 1
        result.append(f"{count}{char}")
        i += count

    return "".join(result)


def decode(s: str) -> str:
    result = []
    i = 0
    while i < len(s):
        # Extract the count (one or more digits)
        count_str = ""
        while i < len(s) and s[i].isdigit():
            count_str += s[i]
            i += 1

        # Get the character
        if i < len(s):
            char = s[i]
            count = int(count_str)
            result.append(char * count)
            i += 1

    return "".join(result)


def roundtrip(s: str) -> bool:
    return decode(encode(s)) == s


def singleCharEncode(s: str) -> str:
    return encode(s)


