module benchmark/solution

import std/string (chars, repeat)

pure func toRoman(n: int) -> string {
  let r0 = if n >= 1000 then {val: n - (n / 1000) * 1000, acc: repeat("M", n / 1000)} else {val: n, acc: ""};
  let r1 = if r0.val >= 900 then {val: r0.val - 900, acc: "${r0.acc}CM"} else {val: r0.val, acc: r0.acc};
  let r2 = if r1.val >= 500 then {val: r1.val - 500, acc: "${r1.acc}D"} else {val: r1.val, acc: r1.acc};
  let r3 = if r2.val >= 400 then {val: r2.val - 400, acc: "${r2.acc}CD"} else {val: r2.val, acc: r2.acc};
  let r4 = if r3.val >= 100 then {val: r3.val - (r3.val / 100) * 100, acc: "${r3.acc}${repeat("C", r3.val / 100)}"} else {val: r3.val, acc: r3.acc};
  let r5 = if r4.val >= 90 then {val: r4.val - 90, acc: "${r4.acc}XC"} else {val: r4.val, acc: r4.acc};
  let r6 = if r5.val >= 50 then {val: r5.val - 50, acc: "${r5.acc}L"} else {val: r5.val, acc: r5.acc};
  let r7 = if r6.val >= 40 then {val: r6.val - 40, acc: "${r6.acc}XL"} else {val: r6.val, acc: r6.acc};
  let r8 = if r7.val >= 10 then {val: r7.val - (r7.val / 10) * 10, acc: "${r7.acc}${repeat("X", r7.val / 10)}"} else {val: r7.val, acc: r7.acc};
  let r9 = if r8.val >= 9 then {val: r8.val - 9, acc: "${r8.acc}IX"} else {val: r8.val, acc: r8.acc};
  let r10 = if r9.val >= 5 then {val: r9.val - 5, acc: "${r9.acc}V"} else {val: r9.val, acc: r9.acc};
  let r11 = if r10.val >= 4 then {val: r10.val - 4, acc: "${r10.acc}IV"} else {val: r10.val, acc: r10.acc};
  let r12 = if r11.val >= 1 then {val: 0, acc: "${r11.acc}${repeat("I", r11.val)}"} else {val: r11.val, acc: r11.acc};
  r12.acc
}

pure func charVal(c: string) -> int =
  match c {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0
  }

pure func parseRoman(cs: [string], acc: int) -> int =
  match cs {
    [] => acc,
    c :: [] => acc + charVal(c),
    c :: next :: rest =>
      if charVal(c) < charVal(next)
      then parseRoman(next :: rest, acc - charVal(c))
      else parseRoman(next :: rest, acc + charVal(c))
  }

pure func fromRoman(s: string) -> int = parseRoman(chars(s), 0)

pure func roundtrip(n: int) -> bool = fromRoman(toRoman(n)) == n

pure func distinctEncoding(a: int, b: int) -> bool = toRoman(a) != toRoman(b)

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

