type IntSet = SNil | SCons(int, IntSet)

func sLength(s: IntSet) -> int =
  match s {
    SNil => 0,
    SCons(_, rest) => 1 + sLength(rest)
  }

func sMerge(a: IntSet, b: IntSet) -> IntSet =
  match a {
    SNil => b,
    SCons(x, xs) => match b {
      SNil => a,
      SCons(y, ys) =>
        if x < y then SCons(x, sMerge(xs, b))
        else if y < x then SCons(y, sMerge(a, ys))
        else SCons(x, sMerge(xs, ys))
    }
  }

func sIntersect(a: IntSet, b: IntSet) -> IntSet =
  match a {
    SNil => SNil,
    SCons(x, xs) => match b {
      SNil => SNil,
      SCons(y, ys) =>
        if x < y then sIntersect(xs, b)
        else if y < x then sIntersect(a, ys)
        else SCons(x, sIntersect(xs, ys))
    }
  }

func isSortedFrom(prev: int, s: IntSet) -> bool =
  match s {
    SNil => true,
    SCons(x, rest) => if x > prev then isSortedFrom(x, rest) else false
  }

func isSorted(s: IntSet) -> bool =
  match s {
    SNil => true,
    SCons(x, rest) => isSortedFrom(x, rest)
  }

func mergePreservesSorted(a: IntSet, b: IntSet) -> bool =
  isSorted(sMerge(a, b))

func inclusionExclusion(a: IntSet, b: IntSet) -> bool =
  (sLength(sMerge(a, b)) + sLength(sIntersect(a, b))) == (sLength(a) + sLength(b))

func toList(s: IntSet) -> [string] =
  match s {
    SNil => [],
    SCons(x, rest) => show(x) :: toList(rest)
  }

