from typing import Union

# Sorted Integer Set ADT
# A sorted set is either:
# - SNil: empty set
# - SCons(head, tail): non-empty set with head (int) and tail (SortedSet)

class SortedSet:
    pass

class SNil(SortedSet):
    def __repr__(self) -> str:
        return "SNil"

class SCons(SortedSet):
    def __init__(self, head: int, tail: SortedSet) -> None:
        self.head = head
        self.tail = tail

    def __repr__(self) -> str:
        return f"SCons({self.head}, {self.tail})"

def toStr(s: SortedSet) -> str:
    """Convert a sorted set to string representation."""
    elements = []
    current = s
    while isinstance(current, SCons):
        elements.append(str(current.head))
        current = current.tail
    return "{" + ", ".join(elements) + "}"

def sLength(s: SortedSet) -> int:
    """Return the length of a sorted set."""
    count = 0
    current = s
    while isinstance(current, SCons):
        count += 1
        current = current.tail
    return count

def isSorted(s: SortedSet) -> bool:
    """Check if a sorted set maintains the sorted invariant."""
    current = s
    while isinstance(current, SCons):
        if isinstance(current.tail, SCons):
            if current.head >= current.tail.head:
                return False
        current = current.tail
    return True

def hasDuplicates(s: SortedSet) -> bool:
    """Check if a sorted set has duplicates."""
    current = s
    while isinstance(current, SCons):
        if isinstance(current.tail, SCons):
            if current.head == current.tail.head:
                return True
        current = current.tail
    return False

def sMerge(s1: SortedSet, s2: SortedSet) -> SortedSet:
    """Merge two sorted sets (union operation)."""
    if isinstance(s1, SNil):
        return s2
    if isinstance(s2, SNil):
        return s1

    if s1.head < s2.head:
        return SCons(s1.head, sMerge(s1.tail, s2))
    elif s1.head > s2.head:
        return SCons(s2.head, sMerge(s1, s2.tail))
    else:  # s1.head == s2.head
        return SCons(s1.head, sMerge(s1.tail, s2.tail))

def sIntersect(s1: SortedSet, s2: SortedSet) -> SortedSet:
    """Intersect two sorted sets."""
    if isinstance(s1, SNil) or isinstance(s2, SNil):
        return SNil()

    if s1.head < s2.head:
        return sIntersect(s1.tail, s2)
    elif s1.head > s2.head:
        return sIntersect(s1, s2.tail)
    else:  # s1.head == s2.head
        return SCons(s1.head, sIntersect(s1.tail, s2.tail))

def mergePreservesSorted(s1: SortedSet, s2: SortedSet) -> bool:
    """Proof that merge preserves the sorted invariant."""
    merged = sMerge(s1, s2)
    return isSorted(merged) and not hasDuplicates(merged)

def inclusionExclusion(s1: SortedSet, s2: SortedSet) -> bool:
    """
    Proof of the inclusion-exclusion principle:
    |A ∪ B| + |A ∩ B| == |A| + |B|
    """
    union = sMerge(s1, s2)
    intersection = sIntersect(s1, s2)

    len_union = sLength(union)
    len_intersection = sLength(intersection)
    len_s1 = sLength(s1)
    len_s2 = sLength(s2)

    return len_union + len_intersection == len_s1 + len_s2

def main() -> None:
    s1 = SCons(1, SCons(3, SCons(5, SNil())))
    s2 = SCons(2, SCons(3, SCons(4, SNil())))

    print(toStr(sMerge(s1, s2)))
    print(toStr(sIntersect(s1, s2)))
    print(sLength(sMerge(s1, s2)))
    print(isSorted(sMerge(s1, s2)))
    print(mergePreservesSorted(s1, s2))
    print(inclusionExclusion(s1, s2))

if __name__ == "__main__":
    main()

