import std/fs (readFile, writeFile)
import std/string (split, trim, contains, stringToInt)
import std/list (length, drop)
import std/json (encode, jo, ja, kv, js, jnum, Json)
import std/math (intToFloat)
import std/option (Option, Some, None)

func rowToJson(line: string) -> Option[Json] {
  let fields = split(trim(line), ",");
  match fields {
    [name, ageStr, email] =>
      match stringToInt(ageStr) {
        Some(age) =>
          if age > 0 && contains(email, "@")
          then Some(jo([
            kv("name", js(name)),
            kv("age", jnum(intToFloat(age))),
            kv("email", js(email))
          ]))
          else None,
        None => None
      },
    _ => None
  }
}

func collectRows(lines: [string]) -> [Json] =
  match lines {
    [] => [],
    l :: rest =>
      match rowToJson(l) {
        Some(j) => j :: collectRows(rest),
        None => collectRows(rest)
      }
  }

export func main() -> () ! {IO, FS} {
  let csv = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com\n";
  writeFile("users.csv", csv);
  let content = readFile("users.csv");
  let lines = split(content, "\n");
  let dataLines = drop(1, lines);
  let objs = collectRows(dataLines);
  let json = encode(ja(objs));
  writeFile("users.json", json);
  println("Converted ${show(length(objs))} valid rows to users.json")
}

