package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type User struct {
	Name  string `json:"name"`
	Age   int    `json:"age"`
	Email string `json:"email"`
}

func isValidUser(name string, ageStr string, email string) bool {
	// Age must be a positive integer
	age, err := strconv.Atoi(ageStr)
	if err != nil || age <= 0 {
		return false
	}
	// Email must contain "@" symbol
	if !strings.Contains(email, "@") {
		return false
	}
	return true
}

func main() {
	// Create input CSV file
	csvContent := "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com\n"
	err := os.WriteFile("users.csv", []byte(csvContent), 0644)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error writing CSV: %v\n", err)
		os.Exit(1)
	}

	// Read CSV file
	file, err := os.Open("users.csv")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error opening CSV: %v\n", err)
		os.Exit(1)
	}
	defer file.Close()

	var users []User

	scanner := bufio.NewScanner(file)
	lineNum := 0

	for scanner.Scan() {
		line := scanner.Text()
		lineNum++

		// Skip header row
		if lineNum == 1 {
			continue
		}

		fields := strings.Split(line, ",")
		if len(fields) != 3 {
			continue
		}

		name := strings.TrimSpace(fields[0])
		ageStr := strings.TrimSpace(fields[1])
		email := strings.TrimSpace(fields[2])

		if !isValidUser(name, ageStr, email) {
			continue
		}

		age, _ := strconv.Atoi(ageStr)

		users = append(users, User{
			Name:  name,
			Age:   age,
			Email: email,
		})
	}

	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "Error reading CSV: %v\n", err)
		os.Exit(1)
	}

	// Convert to JSON
	jsonData, err := json.MarshalIndent(users, "", "  ")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error marshaling JSON: %v\n", err)
		os.Exit(1)
	}

	// Write JSON to file
	err = os.WriteFile("users.json", jsonData, 0644)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error writing JSON: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Converted %d valid rows to users.json\n", len(users))
}

