const fs = require("fs");
const path = require("path");

function main() {
  const baseDir = __dirname;
  const csvPath = path.join(baseDir, "users.csv");
  const jsonPath = path.join(baseDir, "users.json");

  if (!fs.existsSync(csvPath)) {
    const csvContent = `name,age,email
Alice,30,alice@example.com
Bob,25,bob@example.com
Carol,35,carol@example.com
`;
    fs.writeFileSync(csvPath, csvContent, "utf-8");
  }

  const csvContent = fs.readFileSync(csvPath, "utf-8");
  const lines = csvContent.trim().split(/\r?\n/);

  const headers = lines[0].split(",").map((h) => h.trim());

  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const values = lines[i].split(",").map((v) => v.trim());

    const obj = {};
    for (let j = 0; j < headers.length; j++) {
      obj[headers[j]] = values[j] ?? "";
    }

    const ageVal = Number(obj.age);
    const isValidAge = Number.isInteger(ageVal) && ageVal > 0;
    const isValidEmail = typeof obj.email === "string" && obj.email.includes("@");

    if (isValidAge && isValidEmail) {
      obj.age = ageVal;
      rows.push(obj);
    }
  }

  const jsonStr = JSON.stringify(rows, null, 2);
  fs.writeFileSync(jsonPath, jsonStr + "\n", "utf-8");

  console.log(`Converted ${rows.length} valid rows to users.json`);
}

