module benchmark/solution

type Requirement = Req(string, int, int)
type PackageVersion = PackageVersion(string, int, [Requirement])
type Assignment = Assign(string, int)
type AssignmentLookup = Assigned(int) | Unassigned
type DefinitionLookup = DefinitionFound(PackageVersion) | DefinitionMissing
type Resolution = Resolved([Assignment]) | Conflict

func packageVersionNumber(pv: PackageVersion) -> int =
  match pv {
    PackageVersion(_, version, _) => version
  }

func packageRequirements(pv: PackageVersion) -> [Requirement] =
  match pv {
    PackageVersion(_, _, requirements) => requirements
  }

func assignmentName(assignment: Assignment) -> string =
  match assignment {
    Assign(name, _) => name
  }

func lookupAssignment(name: string, assignments: [Assignment]) -> AssignmentLookup =
  match assignments {
    [] => Unassigned,
    Assign(assignedName, version) :: rest =>
      if assignedName == name then Assigned(version)
      else lookupAssignment(name, rest)
  }

func findDefinition(name: string, version: int, universe: [PackageVersion]) -> DefinitionLookup =
  match universe {
    [] => DefinitionMissing,
    pv :: rest =>
      match pv {
        PackageVersion(packageName, packageVersion, _) =>
          if packageName == name && packageVersion == version
          then DefinitionFound(pv)
          else findDefinition(name, version, rest)
      }
  }

func insertCandidate(candidate: PackageVersion, candidates: [PackageVersion]) -> [PackageVersion] =
  match candidates {
    [] => [candidate],
    first :: rest =>
      if packageVersionNumber(candidate) >= packageVersionNumber(first)
      then candidate :: candidates
      else first :: insertCandidate(candidate, rest)
  }

func availableCandidates(name: string, lo: int, hi: int, universe: [PackageVersion]) -> [PackageVersion] =
  match universe {
    [] => [],
    pv :: rest =>
      match pv {
        PackageVersion(packageName, version, _) => {
          let remaining = availableCandidates(name, lo, hi, rest);
          if packageName == name && version >= lo && version <= hi
          then insertCandidate(pv, remaining)
          else remaining
        }
      }
  }

func resolve(
  universe: [PackageVersion],
  assignments: [Assignment],
  worklist: [Requirement]
) -> Resolution =
  match worklist {
    [] => Resolved(assignments),
    Req(name, lo, hi) :: remaining =>
      match lookupAssignment(name, assignments) {
        Assigned(version) =>
          if version >= lo && version <= hi
          then resolve(universe, assignments, remaining)
          else Conflict,
        Unassigned =>
          tryCandidates(
            universe,
            availableCandidates(name, lo, hi, universe),
            assignments,
            remaining
          )
      }
  }

func tryCandidates(
  universe: [PackageVersion],
  candidates: [PackageVersion],
  assignments: [Assignment],
  remaining: [Requirement]
) -> Resolution =
  match candidates {
    [] => Conflict,
    candidate :: rest =>
      match candidate {
        PackageVersion(name, version, requirements) =>
          match resolve(
            universe,
            Assign(name, version) :: assignments,
            requirements ++ remaining
          ) {
            Resolved(result) => Resolved(result),
            Conflict => tryCandidates(universe, rest, assignments, remaining)
          }
      }
  }

func resolveUniverse(universe: [PackageVersion]) -> Resolution =
  match findDefinition("app", 1, universe) {
    DefinitionFound(app) =>
      resolve(universe, [Assign("app", 1)], packageRequirements(app)),
    DefinitionMissing => Conflict
  }

func insertAssignment(assignment: Assignment, assignments: [Assignment]) -> [Assignment] =
  match assignments {
    [] => [assignment],
    first :: rest =>
      if assignmentName(assignment) <= assignmentName(first)
      then assignment :: assignments
      else first :: insertAssignment(assignment, rest)
  }

func sortAssignments(assignments: [Assignment]) -> [Assignment] =
  match assignments {
    [] => [],
    first :: rest => insertAssignment(first, sortAssignments(rest))
  }

func printAssignments(assignments: [Assignment]) -> () ! {IO} =
  match assignments {
    [] => (),
    Assign(name, version) :: rest => {
      println("${name}=${version}");
      printAssignments(rest)
    }
  }

func printResolution(result: Resolution) -> () ! {IO} =
  match result {
    Conflict => println("conflict"),
    Resolved(assignments) => {
      println("resolved");
      printAssignments(sortAssignments(assignments))
    }
  }

export func main() -> () ! {IO} {
  let universeA = [
    PackageVersion("app", 1, [
      Req("lib", 1, 3),
      Req("util", 3, 3)
    ]),
    PackageVersion("lib", 3, [Req("core", 3, 3)]),
    PackageVersion("lib", 2, [Req("core", 1, 2)]),
    PackageVersion("lib", 1, []),
    PackageVersion("util", 3, [Req("core", 1, 1)]),
    PackageVersion("core", 3, []),
    PackageVersion("core", 2, []),
    PackageVersion("core", 1, [])
  ];
  let universeB = [
    PackageVersion("app", 1, [
      Req("x", 1, 1),
      Req("y", 1, 1)
    ]),
    PackageVersion("x", 1, [Req("core", 1, 1)]),
    PackageVersion("y", 1, [Req("core", 2, 2)]),
    PackageVersion("core", 2, []),
    PackageVersion("core", 1, [])
  ];
  printResolution(resolveUniverse(universeA));
  printResolution(resolveUniverse(universeB))
}

