        3: [("core", 1, 1)]
    },
    "core": {
        3: [],
        2: [],
        1: []
    }
}

UNIVERSE_B = {
    "app": {
        1: [("x", 1, 1), ("y", 1, 1)]
    },
    "x": {
        1: [("core", 1, 1)]
    },
    "y": {
        1: [("core", 2, 2)]
    },
    "core": {
        2: [],
        1: []
    }
}

def resolve_dependencies(universe):
    """
    Resolve package dependencies using backtracking.

    Returns: dict mapping package names to versions if successful, None if failed
    """
    assignment = {"app": 1}
    worklist = universe.get("app", {}).get(1, [])

    def get_available_versions(pkg_name, lo, hi):
        """Get versions of a package that fall within [lo, hi], sorted descending."""
        if pkg_name not in universe:
            return []
        versions = sorted([v for v in universe[pkg_name].keys() if lo <= v <= hi], reverse=True)
        return versions

    def backtrack(current_assignment, current_worklist):
        """
        Recursive backtracking resolver.
        Returns True if a solution is found (modifies current_assignment),
        False otherwise.
        """
        if not current_worklist:
            return True

        dep_name, lo, hi = current_worklist[0]
        remaining_worklist = current_worklist[1:]

        if dep_name in current_assignment:
            assigned_version = current_assignment[dep_name]
            if lo <= assigned_version <= hi:
                return backtrack(current_assignment, remaining_worklist)
            else:
                return False

        available_versions = get_available_versions(dep_name, lo, hi)

        for version in available_versions:
            current_assignment[dep_name] = version
            pkg_requirements = universe.get(dep_name, {}).get(version, [])
            new_worklist = pkg_requirements + remaining_worklist

            if backtrack(current_assignment, new_worklist):
                return True

            del current_assignment[dep_name]

        return False

    if backtrack(assignment, worklist):
        return assignment
    else:
        return None

def format_result(assignment):
    """Format the assignment for output."""
    lines = ["resolved"]
    for pkg_name in sorted(assignment.keys()):
        lines.append(f"{pkg_name}={assignment[pkg_name]}")
    return "\n".join(lines)

def main():
    # Process Universe A
    result_a = resolve_dependencies(UNIVERSE_A)
    if result_a is not None:
        print(format_result(result_a))
    else:
        print("conflict")

    print()

    # Process Universe B
    result_b = resolve_dependencies(UNIVERSE_B)
    if result_b is not None:
        print(format_result(result_b))
    else:
        print("conflict")

    # Now use Claude to verify the results
    conversation_history = []

