module benchmark/solution

type Account = Alice | Bob
type Operation = Dep(Account, int) | Wd(Account, int) | Save | Commit | Restore
type Snapshot = {alice: int, bob: int}
type State = {alice: int, bob: int, snapshots: [Snapshot], failures: int}

pure func balance(state: State, account: Account) -> int ! {} =
  match account {
    Alice => state.alice,
    Bob => state.bob
  }

pure func setBalance(state: State, account: Account, amount: int) -> State ! {} =
  match account {
    Alice => {state | alice: amount},
    Bob => {state | bob: amount}
  }

pure func failWithdrawal(state: State) -> State ! {} =
  match state.snapshots {
    [] => {state | failures: state.failures + 1},
    snapshot :: rest => {
      {
        alice: snapshot.alice,
        bob: snapshot.bob,
        snapshots: rest,
        failures: state.failures + 1
      }
    }
  }

pure func step(state: State, operation: Operation) -> State ! {} =
  match operation {
    Dep(account, amount) =>
      setBalance(state, account, balance(state, account) + amount),
    Wd(account, amount) =>
      if balance(state, account) >= amount then
        setBalance(state, account, balance(state, account) - amount)
      else
        failWithdrawal(state),
    Save => {
      let snapshot = {alice: state.alice, bob: state.bob};
      {state | snapshots: snapshot :: state.snapshots}
    },
    Commit =>
      match state.snapshots {
        [] => {state | failures: state.failures + 1},
        _ :: rest => {state | snapshots: rest}
      },
    Restore =>
      match state.snapshots {
        [] => {state | failures: state.failures + 1},
        snapshot :: rest => {
          {
            alice: snapshot.alice,
            bob: snapshot.bob,
            snapshots: rest,
            failures: state.failures
          }
        }
      }
  }

func process(operations: [Operation], state: State) -> State ! {} =
  match operations {
    [] => state,
    operation :: rest => process(rest, step(state, operation))
  }

export func main() -> () ! {IO} {
  let operations = [
    Save,
    Dep(Alice, 30),
    Save,
    Wd(Bob, 80),
    Wd(Alice, 90),
    Save,
    Wd(Alice, 50),
    Dep(Bob, 25),
    Commit,
    Restore,
    Wd(Bob, 75),
    Commit,
    Dep(Alice, 5)
  ];
  let initial = {alice: 100, bob: 50, snapshots: [], failures: 0};
  let result = process(operations, initial);
  println("alice=${result.alice}");
  println("bob=${result.bob}");
  println("failures=${result.failures}")
}

