from dataclasses import dataclass


@dataclass
class Operation:
    op_type: str
    account: str | None = None
    amount: int | None = None


def main():
    # Initial state
    balances = {"alice": 100, "bob": 50}
    snapshots: list[dict[str, int]] = []
    failures = 0

    # Define operations
    operations = [
        Operation("save"),
        Operation("dep", "alice", 30),
        Operation("save"),
        Operation("wd", "bob", 80),
        Operation("wd", "alice", 90),
        Operation("save"),
        Operation("wd", "alice", 50),
        Operation("dep", "bob", 25),
        Operation("commit"),
        Operation("restore"),
        Operation("wd", "bob", 75),
        Operation("commit"),
        Operation("dep", "alice", 5),
    ]

    # Process each operation
    for op in operations:
        if op.op_type == "dep":
            balances[op.account] += op.amount
        elif op.op_type == "wd":
            if balances[op.account] >= op.amount:
                balances[op.account] -= op.amount
            else:
                # Withdrawal fails
                failures += 1
                if snapshots:
                    # Restore from most recent snapshot
                    balances = snapshots.pop().copy()
        elif op.op_type == "save":
            # Push snapshot of current balances
            snapshots.append(balances.copy())
        elif op.op_type == "commit":
            if snapshots:
                # Remove most recent snapshot
                snapshots.pop()
            else:
                # Commit fails if stack is empty
                failures += 1
        elif op.op_type == "restore":
            if snapshots:
                # Restore from most recent snapshot
                balances = snapshots.pop().copy()
            else:
                # Restore fails if stack is empty
                failures += 1

    # Print results
    print(f"alice={balances['alice']}")
    print(f"bob={balances['bob']}")
    print(f"failures={failures}")


if __name__ == "__main__":
    main()

