package main

import "fmt"

type Result[T any] struct {
	ok    bool
	value T
	err   string
}

func Ok[T any](v T) Result[T] {
	return Result[T]{ok: true, value: v}
}

func Err[T any](msg string) Result[T] {
	return Result[T]{ok: false, err: msg}
}

func (r Result[T]) IsOk() bool {
	return r.ok
}

func (r Result[T]) IsErr() bool {
	return !r.ok
}

func validateAge(age int) Result[int] {
	if age >= 0 && age <= 150 {
		return Ok(age)
	}
	return Err[int]("Age out of range")
}

func calculateRetirementYears(age int) Result[int] {
	if age < 65 {
		return Ok(65 - age)
	}
	return Err[int]("Already retired")
}

func processAge(age int) string {
	result := validateAge(age)
	if result.IsErr() {
		return fmt.Sprintf("Error: %s", result.err)
	}
	result = calculateRetirementYears(result.value)
	if result.IsErr() {
		return fmt.Sprintf("Error: %s", result.err)
	}
	return fmt.Sprintf("Years to retirement: %d", result.value)
}

func main() {
	fmt.Println(processAge(30))
	fmt.Println(processAge(70))
	fmt.Println(processAge(-5))
}

