class Result {
    #tag;
    #value;
    #error;

  static ok(value) {
    const r = new Result();
    r.#tag = "ok";
    r.#value = value;
    return r;
  }

  static err(message) {
    const r = new Result();
    r.#tag = "err";
    r.#error = message;
    return r;
  }

  isOk() {
    return this.#tag === "ok";
  }

  isErr() {
    return this.#tag === "err";
  }

  unwrap() {
    if (this.isErr()) throw new Error(this.#error);
    return this.#value;
  }

  value() {
    return this.#value;
  }

  error() {
    return this.#error;
  }

  map(fn) {
    if (this.isOk()) return Result.ok(fn(this.#value));
    return Result.err(this.#error);
  }

  flat_map(fn) {
    if (this.isOk()) return fn(this.#value);
    return Result.err(this.#error);
  }
}

const validate_age = (age) => {
  if (age < 0 || age > 150) return Result.err("Age out of range");
  return Result.ok(age);
};

const calculate_retirement_years = (age) => {
  if (age >= 65) return Result.err("Already retired");
  return Result.ok(65 - age);
