type PRResult = PRResult(int, int, [int])
type Vec = Vec(int, int, int, int)
type Mat = Mat(int, int, int, int, int, int, int, int, int, int, int, int, int, int, int, int)

func insertDesc(x: int, xs: [int]) -> [int] =
  match xs {
    [] => [x],
    y :: rest => if x >= y then x :: xs else y :: insertDesc(x, rest)
  }

func takeFirst(n: int, xs: [int]) -> [int] =
  if n <= 0 then []
  else match xs {
    [] => [],
    x :: rest => x :: takeFirst(n - 1, rest)
  }

func sumList(xs: [int]) -> int =
  match xs {
    [] => 0,
    x :: rest => x + sumList(rest)
  }

func generatePRNG(i: int, x: int, total: int, largest: [int]) -> PRResult {
  let next = (16807 * x) % 2147483647;
  let nextTotal = (total + next) % 1000000007;
  let nextLargest = takeFirst(10, insertDesc(next, largest));
  if i + 1 == 800 then PRResult(next, nextTotal, nextLargest)
  else generatePRNG(i + 1, next, nextTotal, nextLargest)
}

func mulMod(a: int, b: int) -> int =
  (a * b) % 1000000007

func addMod(a: int, b: int) -> int =
  (a + b) % 1000000007

func dot4(a: int, b: int, c: int, d: int, w: int, x: int, y: int, z: int) -> int =
  addMod(addMod(mulMod(a, w), mulMod(b, x)), addMod(mulMod(c, y), mulMod(d, z)))

