def stack_machine():
    instructions = [
        ("PUSH", 462), ("PUSH", 198), ("OVER", None), ("OVER", None), ("SUB", None),
        ("JMPZ", 12), ("OVER", None), ("OVER", None), ("JMPGT", 4), ("OVER", None),
