    ]

    stack = []
    pc = 0
    steps = 0

    while True:
        steps += 1
        op, arg = instructions[pc]

        if op == "PUSH":
            stack.append(arg)
            pc += 1
        elif op == "SUB":
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
            pc += 1
        elif op == "DUP":
            stack.append(stack[-1])
            pc += 1
        elif op == "OVER":
            stack.append(stack[-2])
            pc += 1
        elif op == "SWAP":
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1
        elif op == "POP":
            stack.pop()
            pc += 1
        elif op == "JMP":
            pc += arg
        elif op == "JMPZ":
            v = stack.pop()
            if v == 0:
