# PART 4: Expression Parser
class Parser:
    def __init__(self, expr):
        self.expr = expr
        self.pos = 0

    def peek(self):
        if self.pos < len(self.expr):
            return self.expr[self.pos]
        return None

    def consume(self):
        c = self.peek()
        self.pos += 1
        return c

    def parse_number(self):
        num = ""
        while self.peek() and self.peek().isdigit():
            num += self.consume()
        return num

    def parse_atom(self):
        if self.peek() == "(":
            self.consume()
            result = self.parse_expr()
            self.consume()
            return result
        elif self.peek() == "-":
            self.consume()
            arg = self.parse_power()
            return f"(-{arg})"
        else:
            return self.parse_number()

    def parse_power(self):
        base = self.parse_atom()
        if self.peek() == "^":
            self.consume()
            exp = self.parse_power()
            return f"({base}^{exp})"
        return base

    def parse_mult(self):
        left = self.parse_power()
        while self.peek() in ["*", "/"]:
            op = self.consume()
            right = self.parse_power()
            left = f"({left}{op}{right})"
        return left

    def parse_add(self):
        left = self.parse_mult()
        while self.peek() in ["+", "-"]:
            op = self.consume()
            right = self.parse_mult()
            left = f"({left}{op}{right})"
        return left

    def parse_expr(self):
        return self.parse_add()

