def glob_match(pattern, string):
    def match_helper(p_idx, s_idx):
        if p_idx == len(pattern):
            return s_idx == len(string)

        if pattern[p_idx] == "*":
            if p_idx + 1 == len(pattern):
                return "/" not in string[s_idx:]
            for i in range(s_idx, len(string) + 1):
                if "/" not in string[s_idx:i] and match_helper(p_idx + 1, i):
                    return True
            return False
        elif pattern[p_idx] == "?":
            if s_idx >= len(string) or string[s_idx] == "/":
                return False
            return match_helper(p_idx + 1, s_idx + 1)
        elif pattern[p_idx] == "[":
            if s_idx >= len(string):
                return False
            end = pattern.index("]", p_idx)
            charset = pattern[p_idx+1:end]
            negate = charset.startswith("!")
            if negate:
                charset = charset[1:]

            char = string[s_idx]
            matched = False
            i = 0
            while i < len(charset):
                if i + 2 < len(charset) and charset[i + 1] == "-":
                    if ord(charset[i]) <= ord(char) <= ord(charset[i + 2]):
                        matched = True
                    i += 3
                else:
                    if charset[i] == char:
                        matched = True
                    i += 1

            if (negate and not matched and char != "/") or (not negate and matched and char != "/"):
                return match_helper(end + 1, s_idx + 1)
            return False
        else:
            if s_idx >= len(string) or pattern[p_idx] != string[s_idx]:
                return False
            return match_helper(p_idx + 1, s_idx + 1)

    return match_helper(0, 0)

