# PART 8: Pattern Avoiding Count
MOD = 1000000007

def count_avoiding(n):
    if n == 0:
        return 1

    memo = {}

    def dp(pos, last_three):
        if pos == n:
            return 1
        if (pos, last_three) in memo:
            return memo[(pos, last_three)]

        result = 0
        for digit in [0, 1]:
            new_three = (last_three * 2 + digit) & 0x7
            if new_three != 0b0110:
                result = (result + dp(pos + 1, new_three)) % MOD

        memo[(pos, last_three)] = result
        return result

    return dp(0, 0)

def count_avoiding_matrix(n):
    if n == 0:
        return 1

    states = {}
    state_id = 0

    for i in range(8):
        if i != 0b0110:
            states[i] = state_id
            state_id += 1

    sz = len(states)
    matrix = [[0] * sz for _ in range(sz)]

    for from_state in states:
        for digit in [0, 1]:
            new_state = ((from_state * 2 + digit) & 0x7)
            if new_state != 0b0110:
                to_state = new_state
                matrix[states[from_state]][states[to_state]] = (matrix[states[from_state]][states[to_state]] + 1) % MOD

    def matrix_mult(A, B):
        sz = len(A)
        C = [[0] * sz for _ in range(sz)]
        for i in range(sz):
            for j in range(sz):
                for k in range(sz):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def matrix_pow(M, exp):
        sz = len(M)
        result = [[1 if i == j else 0 for j in range(sz)] for i in range(sz)]
        base = [row[:] for row in M]

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base)
            base = matrix_mult(base, base)
            exp //= 2

        return result

    M = matrix_pow(matrix, n)

    total = 0
    for i in range(sz):
        total = (total + M[states[0]][i]) % MOD

    return total

print(count_avoiding_matrix(1000000000000000000))
