# PART 9: Emphasis Rendering
def render_emphasis(text):
    import re

    punctuation = set('!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~')

    def is_whitespace(c):
        return c == ' '

    def is_flanking_context(text, pos, direction):
        if direction == "left":
            next_char = text[pos] if pos < len(text) else None
            prev_char = text[pos - 1] if pos > 0 else None
        else:
            next_char = text[pos + 1] if pos + 1 < len(text) else None
            prev_char = text[pos] if pos < len(text) else None

        if next_char is None:
            next_is_ws = True
            next_is_punct = False
        else:
            next_is_ws = is_whitespace(next_char)
            next_is_punct = next_char in punctuation

        if prev_char is None:
            prev_is_ws = True
            prev_is_punct = False
        else:
            prev_is_ws = is_whitespace(prev_char)
            prev_is_punct = prev_char in punctuation

        if direction == "left":
            return not next_is_ws and (not next_is_punct or prev_is_ws or prev_is_punct)
        else:
            return not prev_is_ws and (not prev_is_punct or next_is_ws or next_is_punct)

    runs = []
    i = 0
    while i < len(text):
        if text[i] == "*":
            start = i
            while i < len(text) and text[i] == "*":
                i += 1
            length = i - start
            runs.append({
                "start": start,
                "end": i,
                "original_length": length,
                "remaining": length,
                "can_open": is_flanking_context(text, start, "left"),
                "can_close": is_flanking_context(text, start + length - 1, "right")
            })
        else:
            i += 1

    matches = []
    cursor = 0

    while cursor < len(runs):
        closer = runs[cursor]

        if not closer["can_close"] or closer["remaining"] == 0:
            cursor += 1
            continue

        opener = None
        for i in range(cursor - 1, -1, -1):
            if runs[i]["remaining"] == 0:
                continue
            if not runs[i]["can_open"]:
                continue

            sum_orig = runs[i]["original_length"] + closer["original_length"]
            rule_of_three_blocks = False
            if (closer["can_open"] or runs[i]["can_close"]) and sum_orig % 3 == 0:
                if runs[i]["original_length"] % 3 != 0 or closer["original_length"] % 3 != 0:
                    rule_of_three_blocks = True

            if not rule_of_three_blocks:
                opener = runs[i]
                opener_idx = i
                break

        if opener is None:
            if not closer["can_open"]:
                runs.pop(cursor)
            else:
                cursor += 1
            continue

        if opener["remaining"] >= 2 and closer["remaining"] >= 2:
            star_count = 2
        else:
            star_count = 1

        matches.append({
            "opener_idx": opener_idx,
            "closer_idx": cursor,
            "star_count": star_count
        })

        opener["remaining"] -= star_count
        closer["remaining"] -= star_count

        to_remove = [i for i in range(opener_idx + 1, cursor)]
        for i in reversed(to_remove):
            runs.pop(i)
        cursor -= len(to_remove)

        if opener["remaining"] == 0:
            runs.pop(opener_idx)
            cursor -= 1

        if closer["remaining"] == 0:
            runs.pop(cursor)
        else:
            cursor += 1

    parts = []
    run_idx = 0
    pos = 0

    while run_idx < len(runs):
        run = runs[run_idx]
        if pos < run["start"]:
            parts.append(text[pos:run["start"]])

        inner_matches = [m for m in matches if m["opener_idx"] < run_idx and m["closer_idx"] > run_idx]
        inner_matches.sort(key=lambda m: (m["opener_idx"], -m["closer_idx"]))

        literal_stars = run["remaining"]

        for match in inner_matches:
            tag = "<strong>" if match["star_count"] == 2 else "<em>"
            close_tag = "</strong>" if match["star_count"] == 2 else "</em>"
            parts.append(tag)

        parts.append("*" * literal_stars)

        for match in reversed(inner_matches):
            close_tag = "</strong>" if match["star_count"] == 2 else "</em>"
            parts.append(close_tag)

        pos = run["end"]
        run_idx += 1

    if pos < len(text):
        parts.append(text[pos:])

    return "".join(parts)

