universe_a = {
    ("app", 11): [("lib", 11, 13), ("util", 13, 13)],
    ("lib", 13): [("core", 13, 13)],
    ("lib", 12): [("core", 11, 12)],
    ("lib", 11): [],
    ("util", 13): [("core", 11, 11)],
    ("core", 13): [],
    ("core", 12): [],
    ("core", 11): [],
}

universe_b = {
    ("app", 11): [("x", 11, 11), ("y", 11, 11)],
    ("x", 11): [("core", 11, 11)],
    ("y", 11): [("core", 12, 12)],
    ("core", 12): [],
    ("core", 11): [],
}

def resolve(universe):
    assignment = {"app": 11}
    worklist = [(dep, lo, hi) for dep, lo, hi in universe[("app", 11)]]

    def backtrack():
        if not worklist:
            return True

        dep, lo, hi = worklist.pop(0)

        if dep in assignment:
            if not (lo <= assignment[dep] <= hi):
                worklist.insert(0, (dep, lo, hi))
                return False
            return backtrack()

        available = []
        for pkg, ver in universe:
            if pkg == dep:
                available.append(ver)
        available.sort(reverse=True)

        for ver in available:
            if not (lo <= ver <= hi):
                continue

            assignment[dep] = ver
            new_reqs = universe.get((dep, ver), [])
            saved_worklist = worklist[:]
            worklist[:] = list(new_reqs) + worklist

            if backtrack():
                return True

            worklist[:] = saved_worklist
            del assignment[dep]

        worklist.insert(0, (dep, lo, hi))
        return False

    if backtrack():
        print("resolved")
        for name in sorted(assignment.keys()):
            print(f"{name}={assignment[name]}")
        return True
    else:
        print("conflict")
        return False

resolve(universe_a)
