def glob_match(pattern: str, s: str) -> bool:
    """
    Matches a string against a glob pattern with specific semantics:
    - * matches zero or more characters, but never /
    - ? matches exactly one character, but never /
    - [abc] matches one character in the set
    - [!...] matches one character NOT in the set (but never /)
    - Every other character matches literally
    - The whole pattern must match the whole string (anchored)
    """

    def parse_pattern(pat: str) -> list:
        """Parse pattern into tokens"""
        tokens = []
        i = 0
        while i < len(pat):
            if pat[i] == '*':
                tokens.append(('*', None))
                i += 1
            elif pat[i] == '?':
                tokens.append(('?', None))
                i += 1
            elif pat[i] == '[':
                # Parse character set
                j = i + 1
                negated = False
                if j < len(pat) and pat[j] == '!':
                    negated = True
                    j += 1

                # Find the closing ]
                while j < len(pat) and pat[j] != ']':
                    j += 1

                char_set = pat[i+1:j]
                tokens.append(('set', (char_set, negated)))
                i = j + 1
            else:
                tokens.append(('literal', pat[i]))
                i += 1
        return tokens

    def parse_char_set(char_set: str) -> set:
        """Parse a character set like 'a-c' or 'abc' into a set of characters"""
        result = set()
        i = 0
        while i < len(char_set):
            if i + 2 < len(char_set) and char_set[i + 1] == '-':
                # Range like a-c
                start = ord(char_set[i])
                end = ord(char_set[i + 2])
                for code in range(start, end + 1):
                    result.add(chr(code))
                i += 3
            else:
                # Single character
                result.add(char_set[i])
                i += 1
        return result

    def match_recursive(tokens: list, token_idx: int, s: str, s_idx: int) -> bool:
        # If we've consumed all tokens, we need to have consumed all string
        if token_idx == len(tokens):
            return s_idx == len(s)

        token_type, token_value = tokens[token_idx]

        if token_type == 'literal':
            # Must match the literal character
            if s_idx >= len(s) or s[s_idx] != token_value:
                return False
            return match_recursive(tokens, token_idx + 1, s, s_idx + 1)

        elif token_type == '?':
            # Must match exactly one character that is not /
            if s_idx >= len(s) or s[s_idx] == '/':
                return False
            return match_recursive(tokens, token_idx + 1, s, s_idx + 1)

        elif token_type == 'set':
            char_set_str, negated = token_value
            char_set = parse_char_set(char_set_str)

            if s_idx >= len(s):
                return False

            char = s[s_idx]

            if negated:
                # [!...] - match if NOT in set and not /
                if char == '/' or char in char_set:
                    return False
            else:
                # [...] - match if in set (/ only if explicitly listed)
                if char not in char_set:
                    return False

            return match_recursive(tokens, token_idx + 1, s, s_idx + 1)

        elif token_type == '*':
            # Match zero or more characters (but not /)
            # Try matching zero characters first
            if match_recursive(tokens, token_idx + 1, s, s_idx):
                return True

            # Try matching more characters
            while s_idx < len(s) and s[s_idx] != '/':
                s_idx += 1
                if match_recursive(tokens, token_idx + 1, s, s_idx):
                    return True

            return False

        return False

    tokens = parse_pattern(pattern)
    return match_recursive(tokens, 0, s, 0)


