def contains(x, lst):
    """Check if x is in lst."""
    for item in lst:
        if item == x:
            return True
    return False


def enqueue(x, queue):
    """Add x to the end of queue (a list)."""
    queue.append(x)


def bfs(graph, start):
    """Breadth-first search returning nodes in visit order."""
    visited = []
    queue = []

    enqueue(start, queue)

    while len(queue) > 0:
        node = queue.pop(0)

        if contains(node, visited):
            continue

        visited.append(node)

        for neighbor in graph:
            if node == neighbor[0] and isinstance(neighbor[1], list):
                for n in neighbor[1]:
                    enqueue(n, queue)

    return visited


