package main

import "fmt"

// pipe returns a function that computes g(f(x)).
func pipe(f, g func(int) int) func(int) int {
	return func(x int) int {
		return g(f(x))
	}
}

// subtract returns the curried subtraction: subtract(x)(y) = x - y.
func subtract(x int) func(int) int {
	return func(y int) int {
		return x - y
	}
}

// negate returns the negation of x.
func negate(x int) int {
	return -x
}

func main() {
	// Using partial application (currying): subtract(x)(4) gives us "subtract 4 from x"
	var sub4 func(int) int = func(x int) int {
		return subtract(x)(4)
	}

	// Partial application for double: multiply(2, _) — since Go doesn't have multiply as curried yet.
	multiply := func(a int) func(int) int {
		return func(b int) int {
			return a * b
		}
	}
	double := multiply(2)

	// Compose sub4 then double: pipe(sub4, double)
	sub4ThenDouble := pipe(sub4, double)

	// Apply to 11: (11 - 4) * 2 = 7 * 2 = 14
	result := sub4ThenDouble(11)

	fmt.Printf("Result: %d\n", result)
}

