def median(xs: list[int]) -> int:
    """
    Compute the median of an unsorted list of integers.
    For even-length lists, return the lower of the two middle values.
    """
    if not xs:
        return 0

    sorted_xs = sorted(xs)
    n = len(sorted_xs)

    if n % 2 == 1:
        return sorted_xs[n // 2]
    else:
        return sorted_xs[n // 2 - 1]


