              let cents = floatToInt(round(total * 100.0));
              if total > 5.0 then println("${item}: ${formatCents(cents)}") else ()
            },
            None => ()
          },
          None => ()
        },
        None => ()
      };
      printQualifying(rest)
    }
  }

export func main() -> () ! {IO} {
  let source = "[{\"id\":1,\"item\":\"apple\",\"qty\":5,\"price\":1.50},{\"id\":2,\"item\":\"banana\",\"qty\":3,\"price\":0.75},{\"id\":3,\"item\":\"orange\",\"qty\":8,\"price\":2.00}]";
  match decode(source) {
    Ok(value) => match asArray(value) {
      Some(orders) => printQualifying(orders),
      None => ()
    },
    Err(_) => ()
  }
}

