package main

import (
	"encoding/json"
	"fmt"
	"os"
)

type Order struct {
	ID    int     `json:"id"`
	Item  string  `json:"item"`
	Qty   int     `json:"qty"`
	Price float64 `json:"price"`
}

func main() {
	jsonData := `[{"id":1,"item":"apple","qty":5,"price":1.50},{"id":2,"item":"banana","qty":3,"price":0.75},{"id":3,"item":"orange","qty":8,"price":2.00}]`

	var orders []Order
	if err := json.Unmarshal([]byte(jsonData), &orders); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v", err)
		os.Exit(1)
	}

	for _, o := range orders {
		total := float64(o.Qty) * o.Price
		if total > 5.00 {
			fmt.Printf("%s: %.1f\n", o.Item, total)
		}
	}
}

