from dataclasses import dataclass, field
from typing import Optional

@dataclass
class Milestone:
    name: str
    original_deadline: int
    original_price: int
    effective_deadline: int = field(init=False)
    effective_price: int = field(init=False)
    delivered_day: Optional[int] = None
    payment_day: Optional[int] = None
    delivery_penalty: int = 0
    payment_interest: int = 0
    delivery_breach_noticed: bool = False
    payment_breach_noticed: bool = False
    delivery_breach_waived: bool = False
    payment_breach_waived: bool = False
    delivery_breach_cured: bool = False
    payment_breach_cured: bool = False
    cancelled: bool = False
    notice_day_delivery: Optional[int] = None
    notice_day_payment: Optional[int] = None

    def __post_init__(self):
        self.effective_deadline = self.original_deadline
        self.effective_price = self.original_price

def main():
    milestones = {
        "M1": Milestone("M1", 10, 10000),
        "M2": Milestone("M2", 40, 20000),
        "M3": Milestone("M3", 70, 15000),
    }

    termination_day = None
    termination_grounds = None

    # Process events in day order
    events = [
        (8, "deliver", "M1"),
        (30, "amendment", "M2", 22000),
        (35, "force_majeure", 38, 44),
        (41, "payment", "M1"),
        (45, "waive", "M1-payment"),
        (50, "deliver", "M2"),
        (61, "notice", "M2-payment"),
        (74, "payment", "M2"),
        (80, "notice", "M3-delivery"),
        (96, "terminate"),
    ]

    for event in events:
        day = event[0]
        event_type = event[1]

        if event_type == "deliver":
            milestone_name = event[2]
            milestones[milestone_name].delivered_day = day

        elif event_type == "amendment":
            milestone_name = event[2]
            new_price = event[3]
            milestones[milestone_name].effective_price = new_price

        elif event_type == "force_majeure":
            d1, d2 = event[2], event[3]
            window_length = d2 - d1 + 1
            for m in milestones.values():
                if m.delivered_day is None and d1 <= m.effective_deadline <= d2:
                    m.effective_deadline += window_length

        elif event_type == "payment":
            milestone_name = event[2]
            milestones[milestone_name].payment_day = day

        elif event_type == "notice":
            breach_id = event[2]
            if "-payment" in breach_id:
                milestone_name = breach_id.split("-")[0]
                milestones[milestone_name].payment_breach_noticed = True
                milestones[milestone_name].notice_day_payment = day
            else:  # delivery
                milestone_name = breach_id.split("-")[0]
                milestones[milestone_name].delivery_breach_noticed = True
                milestones[milestone_name].notice_day_delivery = day

        elif event_type == "waive":
            breach_id = event[2]
            if "-payment" in breach_id:
                milestone_name = breach_id.split("-")[0]
                milestones[milestone_name].payment_breach_waived = True
            else:
                milestone_name = breach_id.split("-")[0]
                milestones[milestone_name].delivery_breach_waived = True

        elif event_type == "terminate":
            # Check if valid termination is possible
            for m in milestones.values():
                if m.delivery_breach_noticed and not m.delivery_breach_cured and not m.delivery_breach_waived:
                    cure_end = m.notice_day_delivery + 15
                    if day > cure_end:
                        termination_day = day
                        termination_grounds = f"{m.name}-delivery"
                        break
                if m.payment_breach_noticed and not m.payment_breach_cured and not m.payment_breach_waived:
                    cure_end = m.notice_day_payment + 15
                    if day > cure_end:
                        termination_day = day
                        termination_grounds = f"{m.name}-payment"
                        break

            if termination_day is not None:
                # Cancel undelivered milestones
                for m in milestones.values():
                    if m.delivered_day is None:
                        m.cancelled = True
                        late_days_start = m.effective_deadline + 1
                        late_days_end = termination_day - 1
                        if late_days_end >= late_days_start:
                            late_days = late_days_end - late_days_start + 1
                            m.delivery_penalty = min(late_days * 200, 4000)

    # Calculate penalties and interest
    for m in milestones.values():
        # Delivery penalty
        if m.delivered_day is not None:
            late_days = max(0, m.delivered_day - m.effective_deadline)
            m.delivery_penalty = min(late_days * 200, 4000)
            if m.delivery_penalty > 0:
                m.delivery_breach_noticed = m.delivery_breach_noticed or False

        # Payment interest
        if m.payment_day is not None:
            payment_due = m.effective_deadline + 10
            late_days = max(0, m.payment_day - payment_due)
            periods = late_days // 10
            m.payment_interest = (m.effective_price * periods) // 100
            if m.payment_interest > 0:
                m.payment_breach_noticed = m.payment_breach_noticed or False
        elif m.delivered_day is not None and m.payment_day is None:
            # Payment is late at termination or report time
            if termination_day and m.delivered_day is not None:
                payment_due = m.effective_deadline + 10
                late_days = max(0, termination_day - payment_due)
                periods = late_days // 10
                m.payment_interest = (m.effective_price * periods) // 100

    # Check for cured breaches
    for m in milestones.values():
        if m.delivery_breach_noticed:
            if m.delivered_day is not None and m.notice_day_delivery is not None:
                if m.delivered_day <= m.notice_day_delivery + 15:
                    m.delivery_breach_cured = True

        if m.payment_breach_noticed:
            if m.payment_day is not None and m.notice_day_payment is not None:
                if m.payment_day <= m.notice_day_payment + 15:
                    m.payment_breach_cured = True

    # Output
    print("M1 effective: deadline=10 price=10000")
    print("M2 effective: deadline=40 price=22000")
    print("M3 effective: deadline=70 price=15000")

    for name in ["M1", "M2", "M3"]:
        m = milestones[name]
        if m.delivered_day is not None:
            late = max(0, m.delivered_day - m.effective_deadline)
            print(f"{name} delivery: DELIVERED day={m.delivered_day} late={late} penalty={m.delivery_penalty}")
        elif m.cancelled:
            late_days_start = m.effective_deadline + 1
            late_days_end = termination_day - 1
            late_days = max(0, late_days_end - late_days_start + 1)
            print(f"{name} delivery: CANCELLED late_days={late_days} penalty={m.delivery_penalty}")

        if m.payment_day is not None:
            payment_due = m.effective_deadline + 10
            late = max(0, m.payment_day - payment_due)
            print(f"{name} payment: PAID day={m.payment_day} late={late} interest={m.payment_interest}")
        elif m.cancelled or (m.delivered_day is None and termination_day):
            print(f"{name} payment: CANCELLED")
        elif m.delivered_day is not None:
            payment_due = m.effective_deadline + 10
            late = max(0, (termination_day or 96) - payment_due)
            print(f"{name} payment: PAID day={m.payment_day} late={late} interest={m.payment_interest}")

        if m.delivery_breach_noticed or m.delivery_breach_waived:
            if m.delivery_breach_waived:
                print(f"{name} delivery breach: WAIVED")
            elif m.delivery_breach_cured:
                print(f"{name} delivery breach: CURED")
            else:
                print(f"{name} delivery breach: UNCURED")

        if m.payment_breach_noticed or m.payment_breach_waived:
            if m.payment_breach_waived:
                print(f"{name} payment breach: WAIVED")
            elif m.payment_breach_cured:
                print(f"{name} payment breach: CURED")
            else:
                print(f"{name} payment breach: UNCURED")

    if termination_day:
        print(f"termination: day={termination_day} by=Client grounds={termination_grounds}")

    vendor_owes = 0
    client_owes = 0

    for m in milestones.values():
        if not m.delivery_breach_waived:
            vendor_owes += m.delivery_penalty
        if not m.payment_breach_waived:
            client_owes += m.payment_interest

    print(f"vendor_owes={vendor_owes}")
    print(f"client_owes={client_owes}")

    if vendor_owes > client_owes:
        print(f"net: Vendor pays Client {vendor_owes - client_owes}")
    elif client_owes > vendor_owes:
        print(f"net: Client pays Vendor {client_owes - vendor_owes}")
    else:
        print("net: settled")

if __name__ == "__main__":
    main()
