const logContent = `2024-10-29 10:00:00 INFO User logged in: alice
2024-10-29 10:01:15 ERROR Database connection failed
2024-10-29 10:02:30 INFO User logged in: bob
2024-10-29 10:03:45 WARNING High memory usage: 85%
2024-10-29 10:05:00 ERROR API timeout: /users endpoint
2024-10-29 10:06:15 INFO User logged out: alice`

func main() {
	// Create app.log file
	err := os.WriteFile("app.log", []byte(logContent), 0644)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error writing log file: %v\n", err)
		os.Exit(1)
	}

	// Read and parse the log file
	file, err := os.Open("app.log")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error opening log file: %v\n", err)
		os.Exit(1)
	}
	defer file.Close()

	levelCounts := map[string]int{
		"INFO":    0,
		"ERROR":   0,
		"WARNING": 0,
	}
	var totalLines int
	usersSet := make(map[string]bool)

	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := scanner.Text()
		if len(line) == 0 {
			continue
		}

		totalLines++

		// Parse: "{date} {time} {LEVEL} {message}"
		parts := strings.SplitN(line, " ", 4)
		if len(parts) < 3 || len(parts) < 4 {
			continue
		}

		level := parts[2]
		message := ""
		if len(parts) >= 4 {
			message = parts[3]
		}

		levelCounts[level]++

		// Extract username after "logged in:" or "logged out:"
		if strings.Contains(message, "logged in:") {
			idx := strings.Index(message, "logged in:")
			username := strings.TrimSpace(message[idx+len("logged in:"):])
			if len(username) > 0 {
				usersSet[username] = true
			}
		} else if strings.Contains(message, "logged out:") {
			idx := strings.Index(message, "logged out:")
			username := strings.TrimSpace(message[idx+len("logged out:"):])
			if len(username) > 0 {
				usersSet[username] = true
			}
		}
	}

	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "Error reading log file: %v\n", err)
		os.Exit(1)
	}

	// Build sorted unique users list
	var users []string
	for user := range usersSet {
		users = append(users, user)
	}
	sort.Strings(users)

	// Print results with floor division for percentages
	fmt.Printf("Total log entries: %d\n", totalLines)
	fmt.Printf("INFO: %d (%d%%)\n", levelCounts["INFO"], levelCounts["INFO"]*100/totalLines)
	fmt.Printf("ERROR: %d (%d%%)\n", levelCounts["ERROR"], levelCounts["ERROR"]*100/totalLines)
	fmt.Printf("WARNING: %d (%d%%)\n", levelCounts["WARNING"], levelCounts["WARNING"]*100/totalLines)

	userStr := strings.Join(users, ", ")
	fmt.Printf("Unique users: %s\n", userStr)
}

