module benchmark/solution

import std/string (split, trim, startsWith, substring, length)
import std/list (foldl)
import std/fs (readFile)

type Block = 
  Heading(int, string)
  | Paragraph(string)
  | CodeBlock(string, string)
  | HorizontalRule
  | BlockQuote(string)

type MaybeBlock = 
  NoBlock
  | OpenPara(string)
  | OpenCode(string, string)

type ParseState = ParseState([Block], MaybeBlock)

func emptyParseState() -> ParseState = ParseState([], NoBlock)

func headingLevel(line: string) -> int =
  if startsWith(line, "###### ") then 6
  else if startsWith(line, "##### ") then 5
  else if startsWith(line, "#### ") then 4
  else if startsWith(line, "### ") then 3
  else if startsWith(line, "## ") then 2
  else if startsWith(line, "# ") then 1
  else 0

func isHorizRule(line: string) -> bool =
  let t = trim(line) in
  t == "---" || t == "***" || t == "___"

func mdProcessLine(state: ParseState, line: string) -> ParseState =
  match state {
    ParseState(blocks, NoBlock) =>
      if line == "" then ParseState(blocks, NoBlock)
      else if startsWith(line, "```") then
        let lang = trim(substring(line, 3, length(line))) in
        ParseState(blocks, OpenCode(lang, ""))
      else let level = headingLevel(line) in
      if level > 0 then
        let text = trim(substring(line, level + 1, length(line))) in
        ParseState(blocks ++ [Heading(level, text)], NoBlock)
      else if isHorizRule(line) then
        ParseState(blocks ++ [HorizontalRule], NoBlock)
      else if startsWith(line, "> ") then
        ParseState(blocks ++ [BlockQuote(trim(substring(line, 2, length(line))))], NoBlock)
      else ParseState(blocks, OpenPara(line)),

    ParseState(blocks, OpenPara(text)) =>
      if line == "" then ParseState(blocks ++ [Paragraph(text)], NoBlock)
      else ParseState(blocks, OpenPara("${text}\n${line}")),

    ParseState(blocks, OpenCode(lang, code)) =>
      if startsWith(trim(line), "```") then
        ParseState(blocks ++ [CodeBlock(lang, code)], NoBlock)
      else ParseState(blocks, OpenCode(lang, "${code}${line}\n"))
  }

func flushState(state: ParseState) -> [Block] =
  match state {
    ParseState(blocks, NoBlock) => blocks,
    ParseState(blocks, OpenPara(text)) => blocks ++ [Paragraph(text)],
    ParseState(blocks, OpenCode(lang, code)) => blocks ++ [CodeBlock(lang, code)]
  }

export func parseMarkdown(text: string) -> [Block] {
  let lines = split(text, "\n");
  let state = foldl(mdProcessLine, emptyParseState(), lines);
  flushState(state)
}

func blockTag(block: Block) -> string =
  match block {
    Heading(_, _) => "Heading",
    Paragraph(_) => "Paragraph",
    CodeBlock(_, _) => "CodeBlock",
    HorizontalRule => "HorizontalRule",
    BlockQuote(_) => "BlockQuote"
  }

func printTags(blocks: [Block]) -> () ! {IO} =
  match blocks {
    [] => (),
    b :: rest => { println(blockTag(b)); printTags(rest) }
  }

export func main() -> () ! {IO, FS} {
  let content = readFile("input.md");
  let blocks = parseMarkdown(content);
  printTags(blocks)
}

