func merge(xs []int, ys []int) []int {
	result := make([]int, 0, len(xs)+len(ys))
	i, j := 0, 0
	for i < len(xs) && j < len(ys) {
		if xs[i] <= ys[j] {
			result = append(result, xs[i])
			i++
		} else {
			result = append(result, ys[j])
			j++
		}
	}
	for i < len(xs) {
		result = append(result, xs[i])
		i++
	}
	for j < len(ys) {
		result = append(result, ys[j])
		j++
	}
	return result
}

func split(xs []int) ([]int, []int) {
	mid := len(xs) / 2
	left := make([]int, mid)
	copy(left, xs[:mid])
	right := make([]int, len(xs)-mid)
	copy(right, xs[mid:])
	return left, right
}

func mergeSort(xs []int) []int {
	if len(xs) <= 1 {
		return xs
	}
	left, right := split(xs)
	sortedLeft := mergeSort(left)
	sortedRight := mergeSort(right)
	return merge(sortedLeft, sortedRight)
}

