type Expr = Num(int) | Var(string) | Add(Expr, Expr) | Mul(Expr, Expr) | Let(string, Expr, Expr)

func lookup(name: string, env: [(string, int)]) -> int =
  match env {
    [] => 0,
    (key, value) :: rest =>
      if name == key then value else lookup(name, rest)
  }

func eval(expr: Expr, env: [(string, int)]) -> int =
  match expr {
    Num(value) => value,
    Var(name) => lookup(name, env),
    Add(left, right) => eval(left, env) + eval(right, env),
    Mul(left, right) => eval(left, env) * eval(right, env),
    Let(name, boundExpr, body) => {
      let value = eval(boundExpr, env);
      eval(body, (name, value) :: env)
    }
  }

