import std/string (chars)

type Expr = Atom(string) | Binary(Expr, string, Expr) | UnaryMinus(Expr)
type Parsed = P(Expr, [string])
type Digits = D(string, [string])

func isDigit(c: string) -> bool =
  c >= "0" && c <= "9"

func parseDigits(cs: [string], acc: string) -> Digits =
  match cs {
    [] => D(acc, []),
    c :: rest =>
      if isDigit(c) then
        parseDigits(rest, "${acc}${c}")
      else
        D(acc, cs)
  }

func parseExpressionText(text: string) -> Expr =
  match parseAdd(chars(text)) {
    P(expr, _) => expr
  }

func parseAdd(cs: [string]) -> Parsed =
  match parseMultiply(cs) {
    P(left, rest) => parseAddTail(left, rest)
  }

func parseAddTail(left: Expr, cs: [string]) -> Parsed =
  match cs {
    [] => P(left, []),
    op :: rest =>
      if op == "+" || op == "-" then
        match parseMultiply(rest) {
          P(right, remaining) =>
            parseAddTail(Binary(left, op, right), remaining)
        }
      else
        P(left, cs)
  }

func parseMultiply(cs: [string]) -> Parsed =
  match parseUnary(cs) {
    P(left, rest) => parseMultiplyTail(left, rest)
  }

func parseMultiplyTail(left: Expr, cs: [string]) -> Parsed =
  match cs {
    [] => P(left, []),
    op :: rest =>
      if op == "*" || op == "/" then
        match parseUnary(rest) {
          P(right, remaining) =>
            parseMultiplyTail(Binary(left, op, right), remaining)
        }
      else
        P(left, cs)
  }

func parseUnary(cs: [string]) -> Parsed =
  match cs {
    "-" :: rest =>
      match parseUnary(rest) {
        P(operand, remaining) => P(UnaryMinus(operand), remaining)
      },
    _ => parsePower(cs)
  }

func parsePower(cs: [string]) -> Parsed =
  match parsePrimary(cs) {
    P(base, "^" :: rest) =>
      match parseUnary(rest) {
        P(exponent, remaining) =>
          P(Binary(base, "^", exponent), remaining)
      },
    P(base, remaining) => P(base, remaining)
  }

func parsePrimary(cs: [string]) -> Parsed =
  match cs {
    [] => P(Atom(""), []),
    "(" :: rest =>
      match parseAdd(rest) {
        P(expr, remaining) =>
          match remaining {
            ")" :: after => P(expr, after),
            _ => P(expr, remaining)
          }
      },
    _ =>
      match parseDigits(cs, "") {
        D(number, remaining) => P(Atom(number), remaining)
      }
  }

