def tokenize(expr):
    """Tokenize an expression into a list of tokens."""
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif expr[i] in '+-*/^':
            tokens.append(('OP', expr[i]))
            i += 1
        elif expr[i] == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif expr[i] == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        else:
            i += 1
    return tokens


class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def current_token(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected_type=None):
        token = self.current_token()
        if expected_type and token and token[0] != expected_type:
            raise ValueError(f"Expected {expected_type}, got {token[0]}")
        self.pos += 1
        return token

    def parse(self):
        return self.parse_additive()

    def parse_additive(self):
        left = self.parse_multiplicative()

        while self.current_token() and self.current_token()[0] == 'OP' and self.current_token()[1] in '+-':
            op = self.consume()[1]
            right = self.parse_multiplicative()
            left = (op, left, right)

        return left

    def parse_multiplicative(self):
        left = self.parse_unary_minus()

        while self.current_token() and self.current_token()[0] == 'OP' and self.current_token()[1] in '*/':
            op = self.consume()[1]
            right = self.parse_unary_minus()
            left = (op, left, right)

        return left

    def parse_unary_minus(self):
        if self.current_token() and self.current_token()[0] == 'OP' and self.current_token()[1] == '-':
            self.consume()
            operand = self.parse_unary_minus()
            return ('-', operand)

        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()

        if self.current_token() and self.current_token()[0] == 'OP' and self.current_token()[1] == '^':
            self.consume()
            exponent = self.parse_power()
            return ('^', base, exponent)

        return base

    def parse_atom(self):
        token = self.current_token()

        if token and token[0] == 'NUM':
            self.consume()
            return token[1]
        elif token and token[0] == 'LPAREN':
            self.consume()
            expr = self.parse_additive()
            self.consume('RPAREN')
            return expr
        else:
            raise ValueError(f"Unexpected token: {token}")


def ast_to_string(ast):
    """Convert an AST to a fully parenthesized string."""
    if isinstance(ast, int):
        return str(ast)
    elif isinstance(ast, tuple):
        if len(ast) == 2:
            op, operand = ast
            if op == '-':
                return f"(-{ast_to_string(operand)})"
        elif len(ast) == 3:
            op, left, right = ast
            return f"({ast_to_string(left)}{op}{ast_to_string(right)})"
    raise ValueError(f"Invalid AST: {ast}")


def main():
    expressions = [
        "-2^2",
        "2^3^2",
        "8-4-2",
        "2^-3*4",
        "--5+1",
        "-2^-2^3",
        "(1+2)*-3",
        "100-10*-2^2",
    ]

    for expr in expressions:
        tokens = tokenize(expr)
        parser = Parser(tokens)
        ast = parser.parse()
        result = ast_to_string(ast)
        print(result)


if __name__ == "__main__":
    main()

