package main

import "fmt"

// Tree is the algebraic data type representing a binary tree.
// Match enables exhaustive pattern matching (visitor-style).
type Tree interface {
	Match(leafFn func(int) int, nodeFn func(Tree, int, Tree) int) int
}

// Leaf matches the Leaf(value: int) constructor.
type Leaf struct {
	value int
}

func NewLeaf(value int) Tree {
	return Leaf{value: value}
}

// Match exhaustively handles the Leaf case (only one possibility).
func (l Leaf) Match(leafFn func(int) int, nodeFn func(Tree, int, Tree) int) int {
	return leafFn(l.value)
}

// Node matches the Node(left: Tree, value: int, right: Tree) constructor.
type Node struct {
	left  Tree
	value int
	right Tree
}

func NewNode(left Tree, value int, right Tree) Tree {
	return Node{left: left, value: value, right: right}
}

// Match exhaustively handles the Node case (only one possibility).
func (n Node) Match(leafFn func(int) int, nodeFn func(Tree, int, Tree) int) int {
	return nodeFn(n.left, n.value, n.right)
}

// treeSum uses pattern matching to sum all values in the tree.
// - Leaf(v): returns v
// - Node(l, v, r): recursively sums left subtree + value + right subtree
func treeSum(t Tree) int {
	return t.Match(
		func(v int) int {
			return v
		},
		func(left Tree, v int, right Tree) int {
			return treeSum(left) + v + treeSum(right)
		},
	)
}

// findMax uses pattern matching with guards to find the maximum value in the tree.
// - Leaf(v): returns v
// - Node(l, v, r): computes max via guard conditions across recursive subtrees
func findMax(t Tree) int {
	return t.Match(
		func(v int) int {
			return v
		},
		func(left Tree, v int, right Tree) int {
			lMax := findMax(left)
			rMax := findMax(right)

			result := v
			if result < lMax {
				result = lMax
			}
			if result < rMax {
				result = rMax
			}
			return result
		},
	)
}

func main() {
	// Sample tree: Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)))
	tree := NewNode(
		NewLeaf(1),
		5,
		NewNode(NewLeaf(3), 7, NewLeaf(2)),
	)

	sum := treeSum(tree)
	max := findMax(tree)

	fmt.Printf("Sum: %d\n", sum)
	fmt.Printf("Max: %d\n", max)
}

