// Algebraic Data Types — discriminated unions via tagged objects

const Leaf = (value) => ({ __discriminant: 'Leaf', value });
const Node = (left, value, right) => ({
  __discriminant: 'Node',
  left,
  value,
  right,
});

// tree_sum — pattern matching over constructors, exhaustively covering all cases
function treeSum(tree) {
  if (tree.__discriminant === 'Leaf') {
    return tree.value;
  } else if (tree.__discriminant === 'Node') {
    return treeSum(tree.left) + tree.value + treeSum(tree.right);
  } else {
    throw new Error(`exhaustiveness check failed: unknown case`);
  }
}

// find_max — nested pattern matching with guards for the Node variant
function findMax(tree) {
  if (tree.__discriminant === 'Leaf') {
    // base case: leaf returns its own value
    return tree.value;
  } else if (tree.__discriminant === 'Node') {
    // recursive cases for left and right subtrees
    const leftMax = findMax(tree.left);
    const rightMax = findMax(tree.right);

    let max = tree.value;
    if (leftMax > max) max = leftMax;   // guard: compare with left max
    if (rightMax > max) max = rightMax; // guard: compare with right max
    return max;
  } else {
    throw new Error(`exhaustiveness check failed: unknown case`);
  }
}

