package main

import (
	"fmt"
	"sort"
)

func top3(xs []interface{}) []interface{} {
	sorted := make([]interface{}, len(xs))
	copy(sorted, xs)

	sort.Slice(sorted, func(i, j int) bool {
		return compare(sorted[i], sorted[j]) > 0
	})

	if len(sorted) > 3 {
		sorted = sorted[:3]
	}
	return sorted
}

func compare(a, b interface{}) int {
	switch va := a.(type) {
	case int:
		vb := b.(int)
		if va < vb {
			return -1
		} else if va > vb {
			return 1
		}
		return 0
	case string:
		vb := b.(string)
		if va < vb {
			return -1
		} else if va > vb {
			return 1
		}
		return 0
	default:
		return 0
	}
}

