package main

import "fmt"

type run struct {
	count int
	char  string
}

func rle(chars []string) []run {
	if len(chars) == 0 {
		return nil
	}

	var result []run
	current := chars[0]
	count := 1

	for i := 1; i < len(chars); i++ {
		if chars[i] == current {
			count++
		} else {
			result = append(result, run{count, current})
			current = chars[i]
			count = 1
		}
	}
	result = append(result, run{count, current})
	return result
}

func main() {
	input := []string{"a", "a", "a", "b", "b", "c", "c", "c", "c", "a"}
	encoded := rle(input)

	fmt.Print("[" + fmt.Sprintf("(%d, %s)", encoded[0].count, encoded[0].char))
	for i := 1; i < len(encoded); i++ {
		fmt.Print(", " + fmt.Sprintf("(%d, %s)", encoded[i].count, encoded[i].char))
	}
	fmt.Println("]")
}

