// Helper: compute run-length encoding of a list of characters
function runLengthEncode(chars) {
    if (chars.length === 0) return [];

    const result = [];
    let currentChar = chars.at(0);
    let count = 1;

    for (let i = 1; i < chars.length; i++) {
        if (chars[i] === currentChar) {
            count++;
        } else {
            result.push([count, currentChar]);
            currentChar = chars[i];
            count = 1;
        }
    }

    // Push the last run
    result.push([count, currentChar]);
    return result;
}

