def run_length_encode(chars):
    if not chars:
        return []

    def encode_recursive(remaining, current_char, current_count, result):
        if not remaining:
            return result + [(current_count, current_char)]

        char = remaining[0]
        rest = remaining[1:]

        if char == current_char:
            return encode_recursive(rest, current_char, current_count + 1, result)
        else:
            new_result = result + [(current_count, current_char)]
            return encode_recursive(rest, char, 1, new_result)

    return encode_recursive(chars[1:], chars[0], 1, [])


def main():
    input_chars = ['a', 'a', 'a', 'b', 'b', 'c', 'c', 'c', 'c', 'a']
    result = run_length_encode(input_chars)
    parts = []
    for count, char in result:
        parts.append(f"({count}, {char})")
    output = "[" + ", ".join(parts) + "]"
    print(output)


if __name__ == "__main__":
    main()

