module benchmark/solution

type BinOp = Add | Sub | Mul
type SrcOperand = SrcVar(string) | SrcLit(int)
type SrcRhs = SrcInput | SrcLiteral(int) | SrcBin(BinOp, SrcOperand, SrcOperand)
type SrcAssign = SrcAssign(string, SrcRhs)

type SOperand = SVar(string) | SLit(int)
type SRhs = SInput | SLiteral(int) | SBin(BinOp, SOperand, SOperand)
type SAssign = SAssign(string, SRhs)

type CountEntry = CountEntry(string, int)
type LatestEntry = LatestEntry(string, string)

type Knowledge = Const(int) | Copy(string) | Opaque
type KnowledgeEntry = KnowledgeEntry(string, Knowledge)

type Kept = KInput(string) | KBin(string, BinOp, SOperand, SOperand)
type Decision = Delete(Knowledge) | Keep(Knowledge, Kept)

func lookupCount(entries: [CountEntry], name: string) -> int =
  match entries {
    [] => 0,
    CountEntry(key, value) :: rest =>
      if key == name then value else lookupCount(rest, name)
  }

func updateCount(entries: [CountEntry], name: string, value: int) -> [CountEntry] =
  match entries {
    [] => [CountEntry(name, value)],
    CountEntry(key, oldValue) :: rest =>
      if key == name
      then CountEntry(key, value) :: rest
      else CountEntry(key, oldValue) :: updateCount(rest, name, value)
  }

func lookupLatest(entries: [LatestEntry], name: string) -> string =
  match entries {
    [] => "${name}.0",
    LatestEntry(key, value) :: rest =>
      if key == name then value else lookupLatest(rest, name)
  }

func updateLatest(entries: [LatestEntry], name: string, value: string) -> [LatestEntry] =
  match entries {
    [] => [LatestEntry(name, value)],
    LatestEntry(key, oldValue) :: rest =>
      if key == name
      then LatestEntry(key, value) :: rest
      else LatestEntry(key, oldValue) :: updateLatest(rest, name, value)
  }

func renameOperand(operand: SrcOperand, latest: [LatestEntry]) -> SOperand =
  match operand {
    SrcLit(value) => SLit(value),
    SrcVar(name) => SVar(lookupLatest(latest, name))
  }

func renameRhs(rhs: SrcRhs, latest: [LatestEntry]) -> SRhs =
  match rhs {
    SrcInput => SInput,
    SrcLiteral(value) => SLiteral(value),
    SrcBin(op, left, right) =>
      SBin(op, renameOperand(left, latest), renameOperand(right, latest))
  }

func renameAssignments(
  instructions: [SrcAssign],
  returnOperand: SrcOperand,
  counts: [CountEntry],
  latest: [LatestEntry]
) -> ([SAssign], SOperand) =
  match instructions {
    [] => ([], renameOperand(returnOperand, latest)),
    SrcAssign(variable, rhs) :: rest => {
      let index = lookupCount(counts, variable);
      let ssaName = "${variable}.${index}";
      let renamedRhs = renameRhs(rhs, latest);
      let nextCounts = updateCount(counts, variable, index + 1);
      let nextLatest = updateLatest(latest, variable, ssaName);
      let renamedRest = renameAssignments(rest, returnOperand, nextCounts, nextLatest);
      match renamedRest {
        (tailInstructions, renamedReturn) =>
          (SAssign(ssaName, renamedRhs) :: tailInstructions, renamedReturn)
      }
    }
  }

func lookupKnowledge(entries: [KnowledgeEntry], name: string) -> Knowledge =
  match entries {
    [] => Opaque,
    KnowledgeEntry(key, value) :: rest =>
      if key == name then value else lookupKnowledge(rest, name)
  }

func updateKnowledge(
  entries: [KnowledgeEntry],
  name: string,
  value: Knowledge
) -> [KnowledgeEntry] =
  match entries {
    [] => [KnowledgeEntry(name, value)],
    KnowledgeEntry(key, oldValue) :: rest =>
      if key == name
      then KnowledgeEntry(key, value) :: rest
      else KnowledgeEntry(key, oldValue) :: updateKnowledge(rest, name, value)
  }

func substitute(operand: SOperand, table: [KnowledgeEntry]) -> SOperand =
  match operand {
    SLit(value) => SLit(value),
    SVar(name) =>
      match lookupKnowledge(table, name) {
        Const(value) => SLit(value),
        Copy(source) => substitute(SVar(source), table),
        Opaque => SVar(name)
      }
  }

func evalOp(op: BinOp, left: int, right: int) -> int =
  match op {
    Add => left + right,
    Sub => left - right,
    Mul => left * right
  }

func classifyNonConstant(
  name: string,
  op: BinOp,
  left: SOperand,
  right: SOperand
) -> Decision =
  match op {
    Sub =>
      match (left, right) {
        (SVar(leftName), SVar(rightName)) =>
          if leftName == rightName
          then Delete(Const(0))
          else Keep(Opaque, KBin(name, op, left, right)),
        (SVar(source), SLit(0)) => Delete(Copy(source)),
        _ => Keep(Opaque, KBin(name, op, left, right))
      },
    Mul =>
      match (left, right) {
        (SVar(_), SLit(0)) => Delete(Const(0)),
        (SLit(0), SVar(_)) => Delete(Const(0)),
        (SVar(source), SLit(1)) => Delete(Copy(source)),
        (SLit(1), SVar(source)) => Delete(Copy(source)),
        _ => Keep(Opaque, KBin(name, op, left, right))
      },
    Add =>
      match (left, right) {
        (SVar(source), SLit(0)) => Delete(Copy(source)),
        (SLit(0), SVar(source)) => Delete(Copy(source)),
        _ => Keep(Opaque, KBin(name, op, left, right))
      }
  }

func classify(
  name: string,
  rhs: SRhs,
  table: [KnowledgeEntry]
) -> Decision =
  match rhs {
    SInput => Keep(Opaque, KInput(name)),
    SLiteral(value) => Delete(Const(value)),
    SBin(op, originalLeft, originalRight) => {
      let left = substitute(originalLeft, table);
      let right = substitute(originalRight, table);
      match (left, right) {
        (SLit(leftValue), SLit(rightValue)) =>
          Delete(Const(evalOp(op, leftValue, rightValue))),
        _ => classifyNonConstant(name, op, left, right)
      }
    }
  }

func simplify(
  instructions: [SAssign],
  table: [KnowledgeEntry],
  returnOperand: SOperand
) -> ([Kept], SOperand) =
  match instructions {
    [] => ([], substitute(returnOperand, table)),
    SAssign(name, rhs) :: rest =>
      match classify(name, rhs, table) {
        Delete(knowledge) => {
          let nextTable = updateKnowledge(table, name, knowledge);
          simplify(rest, nextTable, returnOperand)
        },
        Keep(knowledge, instruction) => {
          let nextTable = updateKnowledge(table, name, knowledge);
          let simplifiedRest = simplify(rest, nextTable, returnOperand);
          match simplifiedRest {
            (tailInstructions, finalReturn) =>
              (instruction :: tailInstructions, finalReturn)
          }
        }
      }
  }

func containsName(names: [string], target: string) -> bool =
  match names {
    [] => false,
    name :: rest =>
      if name == target then true else containsName(rest, target)
  }

func addName(names: [string], name: string) -> [string] =
  if containsName(names, name) then names else name :: names

func addOperandDependency(names: [string], operand: SOperand) -> [string] =
  match operand {
    SLit(_) => names,
    SVar(name) => addName(names, name)
  }

func keptName(instruction: Kept) -> string =
  match instruction {
    KInput(name) => name,
    KBin(name, _, _, _) => name
  }

func addDependencies(names: [string], instruction: Kept) -> [string] =
  match instruction {
    KInput(_) => names,
    KBin(_, _, left, right) => {
      let withLeft = addOperandDependency(names, left);
      addOperandDependency(withLeft, right)
    }
  }

func eliminateDead(
  instructions: [Kept],
  needed: [string]
) -> ([Kept], [string]) =
  match instructions {
    [] => ([], needed),
    instruction :: rest => {
      let processedRest = eliminateDead(rest, needed);
      match processedRest {
        (liveRest, neededAfterRest) =>
          if containsName(neededAfterRest, keptName(instruction))
          then {
            let expandedNeeded = addDependencies(neededAfterRest, instruction);
            (instruction :: liveRest, expandedNeeded)
          }
          else (liveRest, neededAfterRest)
      }
    }
  }

func initialNeeded(returnOperand: SOperand) -> [string] =
  match returnOperand {
    SLit(_) => [],
    SVar(name) => [name]
  }

func renderOperand(operand: SOperand) -> string =
  match operand {
    SLit(value) => "${value}",
    SVar(name) => name
  }

func renderOp(op: BinOp) -> string =
  match op {
    Add => "+",
    Sub => "-",
    Mul => "*"
  }

func printInstructions(instructions: [Kept]) -> () ! {IO} =
  match instructions {
    [] => (),
    instruction :: rest => {
      match instruction {
        KInput(name) => println("${name} = input"),
        KBin(name, op, left, right) =>
          println("${name} = ${renderOperand(left)} ${renderOp(op)} ${renderOperand(right)}")
      };
      printInstructions(rest)
    }
  }

export func main() -> () ! {IO} {
  let program = [
    SrcAssign("n", SrcInput),
    SrcAssign("m", SrcInput),
    SrcAssign("a", SrcLiteral(7)),
    SrcAssign("a", SrcBin(Sub, SrcVar("a"), SrcLit(7))),
    SrcAssign("c", SrcBin(Mul, SrcVar("n"), SrcVar("a"))),
    SrcAssign("n", SrcBin(Add, SrcVar("n"), SrcVar("c"))),
    SrcAssign("q", SrcBin(Mul, SrcVar("m"), SrcLit(3))),
    SrcAssign("e", SrcBin(Mul, SrcVar("n"), SrcLit(7))),
    SrcAssign("f", SrcBin(Sub, SrcVar("e"), SrcVar("e"))),
    SrcAssign("e", SrcBin(Add, SrcVar("e"), SrcVar("f"))),
    SrcAssign("r", SrcBin(Mul, SrcVar("e"), SrcLit(1)))
  ];
  let renamed = renameAssignments(program, SrcVar("r"), [], []);
  match renamed {
    (ssaInstructions, ssaReturn) => {
      let simplified = simplify(ssaInstructions, [], ssaReturn);
      match simplified {
        (keptInstructions, finalReturn) => {
          let liveResult = eliminateDead(keptInstructions, initialNeeded(finalReturn));
          match liveResult {
            (liveInstructions, _) => {
              printInstructions(liveInstructions);
              println("return ${renderOperand(finalReturn)}")
            }
          }
        }
      }
    }
  }
}

