from dataclasses import dataclass
from typing import Union

@dataclass
class Const:
    value: int

@dataclass
class Copy:
    source: str

@dataclass
class Opaque:
    pass

Mapping = Union[Const, Copy, Opaque]

def main():
    # Represent the program as data
    instructions = [
        ("n", "input", None, None),
        ("m", "input", None, None),
        ("a", None, None, 7),
        ("a", "a", "-", 7),
        ("c", "n", "*", "a"),
        ("n", "n", "+", "c"),
        ("q", "m", "*", 3),
        ("e", "n", "*", 7),
        ("f", "e", "-", "e"),
        ("e", "e", "+", "f"),
        ("r", "e", "*", 1),
    ]
    return_var = "r"

    # PASS 1: SSA Renaming
    ssa_names = {}  # (var_name) -> count
    ssa_instructions = []

    for var, op1, operator, op2 in instructions:
        if var not in ssa_names:
            ssa_names[var] = 0
        else:
            ssa_names[var] += 1

        ssa_name = f"{var}.{ssa_names[var]}"

        # Resolve operand references
        resolved_op1 = None
        resolved_op2 = None

        if op1 is not None:
            if isinstance(op1, str) and op1 not in ["input"]:
                resolved_op1 = f"{op1}.{ssa_names.get(op1, 0) - 1}" if op1 in ssa_names else op1
            else:
                resolved_op1 = op1

        if op2 is not None:
            if isinstance(op2, str):
                resolved_op2 = f"{op2}.{ssa_names.get(op2, 0) - 1}" if op2 in ssa_names else op2
            else:
                resolved_op2 = op2

        ssa_instructions.append((ssa_name, resolved_op1, operator, resolved_op2))

    # PASS 2: Forward Simplification
    table = {}  # ssa_name -> Mapping
    kept_instructions = []

    for ssa_name, op1, operator, op2 in ssa_instructions:
        # Substitute operands
        def resolve_operand(operand):
            if operand is None or operand == "input":
                return operand
            if isinstance(operand, int):
                return operand
            if operand in table:
                mapping = table[operand]
                if isinstance(mapping, Const):
                    return mapping.value
                elif isinstance(mapping, Copy):
                    return resolve_operand(mapping.source)
            return operand

        sub_op1 = resolve_operand(op1)
        sub_op2 = resolve_operand(op2)

        # Classify
        if operator is None and sub_op1 == "input":
            table[ssa_name] = Opaque()
            kept_instructions.append((ssa_name, sub_op1, operator, sub_op2, True))
        elif operator is None:
            table[ssa_name] = Const(sub_op1)
        elif isinstance(sub_op1, int) and isinstance(sub_op2, int):
            result = eval(f"{sub_op1} {operator} {sub_op2}")
            table[ssa_name] = Const(result)
        elif operator == "-" and sub_op1 == sub_op2:
            table[ssa_name] = Const(0)
        elif operator == "*" and (sub_op1 == 0 or sub_op2 == 0):
            table[ssa_name] = Const(0)
        elif operator == "*" and (sub_op1 == 1 or sub_op2 == 1):
            source = sub_op2 if sub_op1 == 1 else sub_op1
            table[ssa_name] = Copy(source)
        elif operator == "+" and (sub_op1 == 0 or sub_op2 == 0):
            source = sub_op2 if sub_op1 == 0 else sub_op1
            table[ssa_name] = Copy(source)
        elif operator == "-" and sub_op2 == 0:
            table[ssa_name] = Copy(sub_op1)
        else:
            table[ssa_name] = Opaque()
            kept_instructions.append((ssa_name, sub_op1, operator, sub_op2, True))

    # Resolve return operand
    def final_resolve(operand):
        if operand is None or operand == "input" or isinstance(operand, int):
            return operand
        if operand in table:
            mapping = table[operand]
            if isinstance(mapping, Const):
                return mapping.value
            elif isinstance(mapping, Copy):
                return final_resolve(mapping.source)
        return operand

    # PASS 3: Dead Code Elimination
    # Build dependency graph
    def get_dependencies(operand):
        if operand is None or operand == "input" or isinstance(operand, int):
            return set()
        if operand in table:
            mapping = table[operand]
            if isinstance(mapping, Const):
                return set()
            elif isinstance(mapping, Copy):
                return {mapping.source} | get_dependencies(mapping.source)
        return {operand}

    return_operand = final_resolve(return_var + "." + str(ssa_names.get(return_var, 0)))
    reachable = get_dependencies(return_operand)

    # Collect all dependencies transitively
    seen = set()
    while reachable - seen:
        new = reachable - seen
        seen.update(new)
        for dep in new:
            if dep in table:
                mapping = table[dep]
                if isinstance(mapping, Opaque):
                    # Find instruction
                    for ssa_name, op1, operator, op2, _ in kept_instructions:
                        if ssa_name == dep:
                            reachable.add(final_resolve(op1) if isinstance(final_resolve(op1), str) else None)
                            reachable.add(final_resolve(op2) if isinstance(final_resolve(op2), str) else None)

    reachable.discard(None)

    # Output surviving instructions
    for ssa_name, op1, operator, op2, _ in kept_instructions:
        if ssa_name in reachable:
            print(f"{ssa_name} = {op1} {operator} {op2}")

    return_val = final_resolve(return_var + "." + str(ssa_names.get(return_var, 0)))
    print(f"return {return_val}")

if __name__ == "__main__":
    main()

