module benchmark/solution

type State = Idle(int) | Moving(int, int) | DoorOpen(int, int)
type Event = Call(int) | Tick | Arrive

func transition(state: State, event: Event) -> State =
  match state {
    Idle(floor) => match event {
      Call(target) =>
        if target == floor then DoorOpen(floor, 3)
        else Moving(floor, target),
      Tick => Idle(floor),
      Arrive => Idle(floor)
    },
    Moving(cur, target) => match event {
      Call(_) => Moving(cur, target),
      Tick => Moving(cur, target),
      Arrive => DoorOpen(target, 3)
    },
    DoorOpen(floor, timer) => match event {
      Call(_) => DoorOpen(floor, timer),
      Tick =>
        if timer > 1 then DoorOpen(floor, timer - 1)
        else Idle(floor),
      Arrive => DoorOpen(floor, timer)
    }
  }

func display(state: State) -> string =
  match state {
    Idle(floor) => "IDLE @ floor ${floor}",
    Moving(cur, target) => "MOVING ${cur} -> ${target}",
    DoorOpen(floor, timer) => "DOOR_OPEN @ floor ${floor} (${timer}sec)"
  }

export func main() -> () ! {IO} {
  let s0 = Idle(1);
  let s1 = transition(s0, Call(5));
  println(display(s1));
  let s2 = transition(s1, Tick);
  println(display(s2));
  let s3 = transition(s2, Tick);
