package main

import "fmt"

// State represents elevator states using a tagged union pattern.
type State interface {
	isState()
}

// Idle represents the idle state at a given floor.
type Idle struct {
	Floor int
}

func (Idle) isState() {}

// Moving represents the elevator moving from one floor to another.
type Moving struct {
	Current int
	Target  int
}

func (Moving) isState() {}

// DoorOpen represents the doors being open with a countdown timer.
type DoorOpen struct {
	Floor int
	Timer int
}

func (DoorOpen) isState() {}

// Event represents incoming events to the state machine.
type Event interface {
	isEvent()
}

// Call represents a call to go to a specific floor.
type Call struct {
	Floor int
}

func (Call) isEvent() {}

// Tick represents one second passing.
type Tick struct{}

func (Tick) isEvent() {}

// Arrive represents the elevator reaching its target floor.
type Arrive struct{}

func (Arrive) isEvent() {}

// transition applies an event to a state and returns the new state.
func transition(state State, event Event) State {
	switch s := state.(type) {
	case Idle:
		switch event.(type) {
		case Call:
			e := event.(Call)
			if e.Floor == s.Floor {
				return DoorOpen{Floor: s.Floor, Timer: 3}
			}
			return Moving{Current: s.Floor, Target: e.Floor}
		default:
			return state
		}
	case Moving:
		switch event.(type) {
		case Tick:
			return state
		case Arrive:
			return DoorOpen{Floor: s.Target, Timer: 3}
		default:
			return state
		}
	case DoorOpen:
		switch event.(type) {
		case Tick:
			if s.Timer > 1 {
				return DoorOpen{Floor: s.Floor, Timer: s.Timer - 1}
			}
			return Idle{Floor: s.Floor}
		default:
			return state
		}
	default:
		return state
	}
}

