// Algebraic Data Types for State
const Idle = (floor) => ({ type: 'Idle', floor });
const Moving = (cur, target) => ({ type: 'Moving', cur, target });
const DoorOpen = (floor, timer) => ({ type: 'DoorOpen', floor, timer });

// Algebraic Data Types for Events
const Call = (floor) => ({ type: 'Call', floor });
const Tick = () => ({ type: 'Tick' });
const Arrive = () => ({ type: 'Arrive' });

// Exhaustive transition function (pattern matching via switch/case)
function transition(state, event) {
  switch (state.type) {
    case 'Idle':
      switch (event.type) {
        case 'Call':
          if (event.floor === state.floor) {
            return DoorOpen(state.floor, 3);
          } else {
            return Moving(state.floor, event.floor);
          }
        case 'Tick':
          return state;
        case 'Arrive':
          return state;
      }
    case 'Moving':
      switch (event.type) {
        case 'Call':
          return state;
        case 'Tick':
          return Moving(state.cur, state.target);
        case 'Arrive':
          return DoorOpen(state.target, 3);
      }
    case 'DoorOpen':
      switch (event.type) {
        case 'Call':
          return state;
        case 'Tick':
          if (state.timer > 1) {
            return DoorOpen(state.floor, state.timer - 1);
          } else {
            return Idle(state.floor);
          }
        case 'Arrive':
          return state;
      }
    default:
      return state;
  }
}

// Display function (exhaustive pattern matching)
function display(state) {
  switch (state.type) {
    case 'Idle':
      return `IDLE @ floor ${state.floor}`;
    case 'Moving':
      return `MOVING ${state.cur} -> ${state.target}`;
    case 'DoorOpen':
      return `DOOR_OPEN @ floor ${state.floor} (${state.timer}sec)`;
    default:
      throw new Error('Unknown state type');
  }
}

