package main

import "fmt"

// State types (algebraic data type via interface + concrete structs)
type State interface {
	state()
	String() string
}

type IdleState struct{}

func (IdleState) state()   {}
func (s IdleState) String() string { return "IDLE" }

type HasCreditState struct{ cents int }

func (HasCreditState) state()         {}
func (s HasCreditState) String() string {
	return fmt.Sprintf("CREDIT(%d)", s.cents)
}

type DispensingState struct{ change int }

func (DispensingState) state()             {}
func (s DispensingState) String() string { return fmt.Sprintf("DISPENSING(%d)", s.change) }

// Event types
type Event interface {
	event()
}

type InsertEvent struct{ cents int }

func (InsertEvent) event() {}

type SelectEvent struct{ code int }

func (SelectEvent) event() {}

type DispenseDoneEvent struct{}

func (DispenseDoneEvent) event() {}

// Result: tagged union wrapping either a new State or an error string
type Result struct {
	state State
	err   string // non-empty means Err
}

func OkState(s State) Result { return Result{state: s, err: ""} }

func ErrResult(reason string) Result { return Result{state: nil, err: reason} }

// step implements the vending machine transition function
func step(currentState State, event Event) Result {
	switch st := currentState.(type) {
	case IdleState:
		switch event.(type) {
		case InsertEvent:
			return OkState(HasCreditState{cents: event.(InsertEvent).cents})
		case SelectEvent:
			return ErrResult("no_credit")
		case DispenseDoneEvent:
			return ErrResult("not_dispensing")
		default:
			panic("unknown event")
		}

	case HasCreditState:
		switch e := event.(type) {
		case InsertEvent:
			return OkState(HasCreditState{cents: st.cents + e.cents})
		case SelectEvent:
			price := 0
			switch e.code {
			case 1: // cola
				price = 125
			case 2: // chips
				price = 75
			case 3: // water
				price = 100
			default:
				return ErrResult("unknown_item")
			}
			if st.cents < price {
				return ErrResult("insufficient_funds")
			}
			return OkState(DispensingState{change: st.cents - price})
		case DispenseDoneEvent:
			return ErrResult("not_dispensing")
		default:
			panic("unknown event")
		}

	case DispensingState:
		switch event.(type) {
		case InsertEvent, SelectEvent:
			return ErrResult("busy")
		case DispenseDoneEvent:
			return OkState(IdleState{})
		default:
			panic("unknown event")
		}

	default:
		panic("unknown state")
	}
}

func printResult(r Result) {
	if r.err != "" {
		fmt.Printf("err: %s\n", r.err)
	} else {
		fmt.Printf("ok: %s\n", r.state)
	}
}

func main() {
	state := State(IdleState{})

	events := []Event{
		InsertEvent{cents: 50},
		SelectEvent{code: 1},
		InsertEvent{cents: 100},
		SelectEvent{code: 1},
		InsertEvent{cents: 50},
		DispenseDoneEvent{},
		SelectEvent{code: 2},
		InsertEvent{cents: 100},
		SelectEvent{code: 2},
		DispenseDoneEvent{},
	}

	for _, event := range events {
		result := step(state, event)
		printResult(result)
		if result.err == "" {
			state = result.state
		}
	}
}

