// Vending machine state machine returning Result<NewState, String>

function Insert(cents) {
  return { type: 'Insert', cents };
}

function Select(code) {
  return { type: 'Select', code };
}

function DispenseDone() {
  return { type: 'DispenseDone' };
}

function idle() {
  return { state: 'Idle' };
}

function hasCredit(cents) {
  return { state: 'HasCredit', cents };
}

function dispensing(change) {
  return { state: 'Dispensing', change };
}

const ITEM_PRICES = { 1: 125, 2: 75, 3: 100 };

function step(state, event) {
  switch (state.state) {
    case 'Idle':
      if (event.type === 'Insert') {
        return { ok: hasCredit(event.cents) };
      }
      return { err: event.type === 'Select' ? 'no_credit' : 'not_dispensing' };

    case 'HasCredit':
      if (event.type === 'Insert') {
        return { ok: hasCredit(state.cents + event.cents) };
      }
      if (event.type === 'Select') {
        const price = ITEM_PRICES[event.code];
        if (price === undefined) {
          return { err: 'unknown_item' };
        }
        if (state.cents < price) {
          return { err: 'insufficient_funds' };
        }
        return { ok: dispensing(state.cents - price) };
      }
      return { err: 'not_dispensing' };

    case 'Dispensing':
      if (event.type === 'Insert' || event.type === 'Select') {
        return { err: 'busy' };
      }
      return { ok: idle() };

    default:
      throw new Error('Unknown state');
  }
}

function formatResult(result) {
  if (result.ok !== undefined) {
    const s = result.ok;
    switch (s.state) {
      case 'Idle':
        return 'ok: IDLE';
      case 'HasCredit':
        return `ok: CREDIT(${s.cents})`;
      case 'Dispensing':
        return `ok: DISPENSING(${s.change})`;
    }
  }
  return `err: ${result.err}`;
}

function main() {
  let state = idle();

  const events = [
    Insert(50),
    Select(1),
    Insert(100),
    Select(1),
    Insert(30),
    DispenseDone(),
    Select(2),
    Insert(100),
    Select(2),
    DispenseDone(),
  ];

  for (const event of events) {
    const result = step(state, event);
    console.log(formatResult(result));
    if (result.ok !== undefined) {
      state = result.ok;
    }
  }
}

main();

