type Expr = Const(int) | Var(string) | Add(Expr, Expr) | Mul(Expr, Expr)

func diff(expr: Expr, variable: string) -> Expr =
  match expr {
    Const(_) => Const(0),
    Var(name) => if name == variable then Const(1) else Const(0),
    Add(a, b) => Add(diff(a, variable), diff(b, variable)),
    Mul(a, b) => Add(Mul(a, diff(b, variable)), Mul(b, diff(a, variable)))
  }

