    Const(0) => b,
    _ => match b {
      Const(0) => a,
      _ => Add(a, b)
    }
  }

func simplifyMul(a: Expr, b: Expr) -> Expr =
  match a {
    Const(0) => Const(0),
    Const(1) => b,
    _ => match b {
      Const(0) => Const(0),
      Const(1) => a,
      _ => Mul(a, b)
    }
  }

func simplify(expr: Expr) -> Expr =
  match expr {
    Const(n) => Const(n),
    Var(name) => Var(name),
    Add(a, b) => simplifyAdd(simplify(a), simplify(b)),
    Mul(a, b) => simplifyMul(simplify(a), simplify(b))
  }

