package main

import (
	"fmt"
)

type Expr interface {
	isExpr()
}

type Const struct {
	Value int
}

func (c *Const) isExpr() {}

type Var struct {
	Name string
}

func (v *Var) isExpr() {}

type Add struct {
	Left  Expr
	Right Expr
}

func (a *Add) isExpr() {}

type Mul struct {
	Left  Expr
	Right Expr
}

func (m *Mul) isExpr() {}

func diff(expr Expr, varName string) Expr {
	switch e := expr.(type) {
	case *Const:
		return &Const{0}
	case *Var:
		if e.Name == varName {
			return &Const{1}
		}
		return &Const{0}
	case *Add:
		l := diff(e.Left, varName)
		r := diff(e.Right, varName)
		return &Add{l, r}
	case *Mul:
		f := e.Left
		g := e.Right
		dg := diff(g, varName)
		df := diff(f, varName)
		first := &Mul{f, dg}
		second := &Mul{g, df}
		return &Add{first, second}
	default:
		return &Const{0}
	}
}

func simplify(expr Expr) Expr {
	switch e := expr.(type) {
	case *Const, *Var:
		return expr
	case *Add:
		e.Left = simplify(e.Left)
		e.Right = simplify(e.Right)
		if l, ok := e.Left.(*Const); ok && l.Value == 0 {
			return e.Right
		}
		if r, ok := e.Right.(*Const); ok && r.Value == 0 {
			return e.Left
		}
		return e
	case *Mul:
		e.Left = simplify(e.Left)
		e.Right = simplify(e.Right)
		if l, ok := e.Left.(*Const); ok && l.Value == 0 {
			return &Const{0}
		}
		if r, ok := e.Right.(*Const); ok && r.Value == 0 {
			return &Const{0}
		}
		if l, ok := e.Left.(*Const); ok && l.Value == 1 {
			return e.Right
		}
		if r, ok := e.Right.(*Const); ok && r.Value == 1 {
			return e.Left
		}
		return e
	default:
		return expr
	}
}

func showExpr(expr Expr) string {
	switch e := expr.(type) {
	case *Const:
		return fmt.Sprintf("%d", e.Value)
	case *Var:
		return e.Name
	case *Add:
		return fmt.Sprintf("(%s + %s)", showExpr(e.Left), showExpr(e.Right))
	case *Mul:
		return fmt.Sprintf("(%s * %s)", showExpr(e.Left), showExpr(e.Right))
	default:
		return "0"
	}
}

func main() {
	expr := &Add{
		Left: &Add{
			Left: &Mul{
				Left:  &Var{"x"},
				Right: &Var{"x"},
			},
			Right: &Mul{
				Left:  &Const{3},
				Right: &Var{"x"},
			},
		},
		Right: &Const{5},
	}

	result := diff(expr, "x")
	simplified := simplify(result)
	fmt.Print(showExpr(simplified))
}

