class Const { constructor(n) { this.n = n; } }
class Var { constructor(name) { this.name = name; } }
class Add { constructor(left, right) { this.left = left; this.right = right; } }
class Mul { constructor(left, right) { this.left = left; this.right = right; } }

function diff(expr, varName) {
  if (expr instanceof Const) return new Const(0);
  if (expr instanceof Var) {
    return expr.name === varName ? new Const(1) : new Const(0);
  }
  if (expr instanceof Add) {
    return new Add(diff(expr.left, varName), diff(expr.right, varName));
  }
  if (expr instanceof Mul) {
    // d/dx(f * g) = f * d/dx(g) + g * d/dx(f)
    return new Add(
      new Mul(expr.left, diff(expr.right, varName)),
      new Mul(expr.right, diff(expr.left, varName))
    );
  }
}

function simplify(expr) {
  if (expr instanceof Const || expr instanceof Var) return expr;

  let left = simplify(expr.left);
  let right = simplify(expr.right);

  if (expr instanceof Add) {
    // If both children are constants, evaluate
    if (left instanceof Const && right instanceof Const) {
      return new Const(left.n + right.n);
    }
    // 0 + e = e
    if (left instanceof Const && left.n === 0) return right;
    // e + 0 = e
    if (right instanceof Const && right.n === 0) return left;
    return new Add(left, right);
  }

  if (expr instanceof Mul) {
    // If both children are constants, evaluate
    if (left instanceof Const && right instanceof Const) {
      return new Const(left.n * right.n);
    }
    // 0 * e = 0, e * 0 = 0
    if ((left instanceof Const && left.n === 0) || (right instanceof Const && right.n === 0)) {
      return new Const(0);
    }
    // 1 * e = e, e * 1 = e
    if (left instanceof Const && left.n === 1) return right;
    if (right instanceof Const && right.n === 1) return left;
    return new Mul(left, right);
  }

  return expr;
}

function showExpr(expr) {
  if (expr instanceof Const) return String(expr.n);
  if (expr instanceof Var) return expr.name;
  if (expr instanceof Add) return `(${showExpr(expr.left)} + ${showExpr(expr.right)})`;
  if (expr instanceof Mul) return `(${showExpr(expr.left)} * ${showExpr(expr.right)})`;
}

function main() {
  // x^2 + 3x + 5 = Add(Add(Mul(Var("x"), Var("x")), Mul(Const(3), Var("x"))), Const(5))
  const expr = new Add(
    new Add(
      new Mul(new Var("x"), new Var("x")),
      new Mul(new Const(3), new Var("x"))
    ),
    new Const(5)
  );

  const derivative = diff(expr, "x");
  const simplified = simplify(derivative);
  console.log(showExpr(simplified));
}

main();

