from dataclasses import dataclass
from typing import Union


@dataclass(frozen=True)
class Const:
    value: int


@dataclass(frozen=True)
class Var:
    name: str


@dataclass(frozen=True)
class Add:
    left: object
    right: object


@dataclass(frozen=True)
class Mul:
    left: object
    right: object


Expr = Union[Const, Var, Add, Mul]


def diff(expr: Expr, var: str) -> Expr:
    match expr:
        case Const(_):
            return Const(0)
        case Var(name):
            if name == var:
                return Const(1)
            else:
                return Const(0)
        case Add(left, right):
            d_left = diff(left, var)
            d_right = diff(right, var)
            return Add(d_left, d_right)
        case Mul(left, right):
            d_left = diff(left, var)
            d_right = diff(right, var)
            return Add(Mul(left, d_right), Mul(right, d_left))


def simplify(expr: Expr) -> Expr:
    match expr:
        case Const(_) | Var(_):
            return expr
        case Add(left, right):
            left = simplify(left)
            right = simplify(right)
            if isinstance(left, Const) and left.value == 0:
                return right
            if isinstance(right, Const) and right.value == 0:
                return left
            return Add(left, right)
        case Mul(left, right):
            left = simplify(left)
            right = simplify(right)
            if isinstance(left, Const) and left.value == 0:
                return Const(0)
            if isinstance(right, Const) and right.value == 0:
                return Const(0)
            if isinstance(left, Const) and left.value == 1:
                return right
            if isinstance(right, Const) and right.value == 1:
                return left
            return Mul(left, right)


def showExpr(expr: Expr) -> str:
    match expr:
        case Const(n):
            return str(n)
        case Var(name):
            return name
        case Add(a, b):
            return f"({showExpr(a)} + {showExpr(b)})"
        case Mul(a, b):
            return f"({showExpr(a)} * {showExpr(b)})"


def main():
    expr = Add(
        Add(Mul(Var("x"), Var("x")), Mul(Const(3), Var("x"))),
        Const(5)
    )
    derivative = diff(expr, "x")
    simplified = simplify(derivative)
    print(showExpr(simplified))


if __name__ == "__main__":
    main()

