package main

import (
	"fmt"
	"strconv"
)

type Tree struct {
	kind  string // "leaf" or "node"
	val   int
	left  *Tree
	right *Tree
}

func leaf(value int) *Tree {
	return &Tree{kind: "leaf", val: value}
}

func node(left *Tree, value int, right *Tree) *Tree {
	return &Tree{kind: "node", val: value, left: left, right: right}
}

func mapTree(fn func(int) int, tree *Tree) *Tree {
	if tree.kind == "leaf" {
		return leaf(fn(tree.val))
	}
	return node(mapTree(fn, tree.left), fn(tree.val), mapTree(fn, tree.right))
}

func foldTree(fn func(int, int) int, acc int, tree *Tree) int {
	if tree.kind == "leaf" {
		return fn(acc, tree.val)
	}
	acc = foldTree(fn, acc, tree.left)
	acc = foldTree(fn, acc, tree.right)
	return fn(acc, tree.val)
}

func treeToList(tree *Tree) []int {
	if tree.kind == "leaf" {
		return []int{tree.val}
	}
	result := treeToList(tree.left)
	result = append(result, tree.val)
	return append(result, treeToList(tree.right)...)
}

func treeDepth(tree *Tree) int {
	if tree.kind == "leaf" {
		return 1
	}
	left := treeDepth(tree.left)
	right := treeDepth(tree.right)
	if left > right {
		return left + 1
	}
	return right + 1
}

func main() {
	tree := node(
		node(leaf(1), 2, leaf(3)),
		4,
		node(leaf(5), 6, leaf(7)),
	)

	double := func(x int) int { return x * 2 }
	add := func(a int, b int) int { return a + b }

	fmt.Printf("[%s]\n", joinInt(", ", treeToList(tree)))
	fmt.Printf("[%s]\n", joinInt(", ", treeToList(mapTree(double, tree))))
	fmt.Println(foldTree(add, 0, tree))
	fmt.Println(treeDepth(tree))
}

func joinInt(sep string, vals []int) string {
	if len(vals) == 0 {
		return ""
	}
	s := strconv.Itoa(vals[0])
	for i := 1; i < len(vals); i++ {
		s += sep + strconv.Itoa(vals[i])
	}
	return s
}

