package main

import "fmt"

type Type interface {
	isType()
}

type TVar struct {
	Name string
}

func (TVar) isType() {}

type TInt struct{}

func (TInt) isType() {}

type TBool struct{}

func (TBool) isType() {}

type TFunc struct {
	Arg   Type
	Res   Type
}

func (TFunc) isType() {}

type Subst []SubstPair

type SubstPair struct {
	Name  string
	Type_ Type
}

func apply(s Subst, t Type) Type {
	switch ty := t.(type) {
	case TVar:
		for _, p := range s {
			if p.Name == ty.Name {
				return apply(s, p.Type_)
			}
		}
		return t
	case TInt, TBool:
		return t
	case *TFunc:
		return &TFunc{apply(s, ty.Arg), apply(s, ty.Res)}
	default:
		return t
	}
}

func unify(t1, t2 Type) (Subst, error) {
	switch a := t1.(type) {
	case TVar:
		return Subst{{a.Name, t2}}, nil
	case *TFunc:
		b, ok := t2.(*TFunc)
		if !ok {
			return nil, fmt.Errorf("cannot unify func with non-func")
		}
		s1, err := unify(a.Arg, b.Arg)
		if err != nil {
			return nil, err
		}
		s2, err := unify(apply(s1, a.Res), apply(s1, b.Res))
		if err != nil {
			return nil, err
		}
		return append(s1, s2...), nil
	default:
		b, ok := t2.(TVar)
		if ok {
			return Subst{{b.Name, t1}}, nil
		}
		if _, isInt := t1.(TInt); isInt {
			if _, ok2 := t2.(TInt); ok2 {
				return nil, nil
			}
		}
		if _, isBool := t1.(TBool); isBool {
			if _, ok2 := t2.(TBool); ok2 {
				return nil, nil
			}
		}
		return nil, fmt.Errorf("cannot unify types")
	}
}

func main() {
	t1 := &TFunc{TVar{"a"}, TInt{}}
	t2 := &TFunc{TBool{}, TVar{"b"}}

	s, err := unify(t1, t2)
	if err != nil {
		fmt.Println("unification failed:", err)
		return
	}

	for _, p := range s {
		fmt.Printf("%s = %s\n", p.Name, typeStr(p.Type_))
	}
}

func typeStr(t Type) string {
	switch ty := t.(type) {
	case TVar:
		return "TVar(\"" + ty.Name + "\")"
	case TInt:
		return "TInt"
	case TBool:
		return "TBool"
	case *TFunc:
		return "TFunc(" + typeStr(ty.Arg) + ", " + typeStr(ty.Res) + ")"
	default:
		return "?"
	}
}

