class TVar {
  constructor(name) { this.name = name; }
}

class TInt {
  constructor() {}
}

class TBool {
  constructor() {}
}

class TFunc {
  constructor(arg, result) {
    this.arg = arg;
    this.result = result;
  }
}

function typeToString(t) {
  if (t instanceof TVar) return `TVar(${t.name})`;
  if (t instanceof TInt) return 'TInt';
  if (t instanceof TBool) return 'TBool';
  if (t instanceof TFunc) return `(${typeToString(t.arg)}) -> (${typeToString(t.result)})`;
}

function applySubst(subst, t) {
  if (t instanceof TVar) {
    for (const s of subst) {
      if (s.name === t.name) {
        return applySubst(subst, s.type);
      }
    }
    return t;
  }
  if (t instanceof TInt || t instanceof TBool) {
    return t;
  }
  if (t instanceof TFunc) {
    return new TFunc(applySubst(subst, t.arg), applySubst(subst, t.result));
  }
}

function unify(t1, t2) {
  let subst = [];
  let pending = [[t1, t2]];

  while (pending.length > 0) {
    const [u1, u2] = pending.shift();
    const a1 = applySubst(subst, u1);
    const a2 = applySubst(subst, u2);

    if (a1 instanceof TInt && a2 instanceof TInt) {
      continue;
    } else if (a1 instanceof TBool && a2 instanceof TBool) {
      continue;
    } else if (a1 instanceof TVar && a2 instanceof TVar) {
      if (a1.name !== a2.name) throw new Error('Types do not unify');
      continue;
    } else if (a1 instanceof TVar) {
      subst.push({ name: a1.name, type: a2 });
    } else if (a2 instanceof TVar) {
      subst.push({ name: a2.name, type: a1 });
    } else if (a1 instanceof TFunc && a2 instanceof TFunc) {
      pending.push([a1.arg, a2.arg]);
      pending.push([a1.result, a2.result]);
    } else {
      throw new Error('Cannot unify types');
    }
  }

  return subst;
}

function main() {
  try {
    const t1 = new TFunc(new TVar('a'), new TInt());
    const t2 = new TFunc(new TBool(), new TVar('b'));
    const subst = unify(t1, t2);

    for (const s of subst) {
      console.log(`${s.name} = ${typeToString(s.type)}`);
    }
  } catch (e) {
    console.log('Unification failed: ' + e.message);
  }
}

