class Type:
    pass

class TVar(Type):
    def __init__(self, name):
        self.name = name
    def __eq__(self, other):
        return isinstance(other, TVar) and self.name == other.name
    def __repr__(self):
        return f"TVar({self.name!r})"

class TInt(Type):
    def __init__(self): pass
    def __eq__(self, other):
        return isinstance(other, TInt)
    def __repr__(self):
        return "TInt"

class TBool(Type):
    def __eq__(self, other):
        return isinstance(other, TBool)
    def __repr__(self):
        return "TBool"

class TFunc(Type):
    def __init__(self, arg, result):
        self.arg = arg
        self.result = result
    def __eq__(self, other):
        return isinstance(other, TFunc) and self.arg == other.arg and self.result == other.result
    def __repr__(self):
        return f"TFunc({self.arg!r}, {self.result!r})"

def apply(subst, t):
    if isinstance(t, TVar):
        for var, typ in subst:
            if var == t.name:
                return apply(subst, typ)
        return t
    elif isinstance(t, TInt) or isinstance(t, TBool):
        return t
    elif isinstance(t, TFunc):
        return TFunc(apply(subst, t.arg), apply(subst, t.result))
    else:
        raise ValueError(f"Unexpected type: {t}")

def unify(t1, t2):
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    if isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    if isinstance(t1, TVar):
        return [(t1.name, t2)]
    if isinstance(t2, TVar):
        return [(t2.name, t1)]
    if isinstance(t1, TFunc) and isinstance(t2, TFunc):
        s1 = unify(t1.arg, t2.arg)
        s2 = unify(apply(s1, t1.result), apply(s1, t2.result))
        return s1 + s2
    raise ValueError(f"Cannot unify {t1} with {t2}")

# Unify TFunc(TVar("a"), TInt) with TFunc(TBool, TVar("b"))
t1 = TFunc(TVar("a"), TInt())
t2 = TFunc(TBool(), TVar("b"))

try:
    subst = unify(t1, t2)
    for var_name, typ in subst:
        print(f"{var_name} = {typ}")
except ValueError as e:
    print(str(e))
